const CERTIFICATION_COURSE=[{"id": "cert3-1.1", "title": "Follow a packet through the layers", "core": 3, "objective": "1.1", "domain": 1, "type": "network", "requires": [], "lore": "Use the OSI model to locate a fault, not to pretend real protocols obey perfect boundaries. Trace a message from application data to transport segments, network packets, link frames, and physical signals.\n\nYOUR TOOLKIT\n\nPhysical — Bits carried as electrical, optical, or radio signals.\n\nData link — Local frame delivery using link-layer addressing and media access.\n\nNetwork — Logical addressing and routing between networks.\n\nTransport — End-to-end transport behavior such as TCP reliability or UDP datagrams.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A link light is off before any address is assigned. Investigate the physical path before changing DNS.", "questions": [{"id": "cert3-1.1-practice-1-1-0", "prompt": "Which concept best fits this description? Bits carried as electrical, optical, or radio signals.", "explanation": "Physical: Bits carried as electrical, optical, or radio signals. The other choices describe different mechanisms or properties.", "options": ["Data link", "Transport", "Network", "Physical"], "answer": 3, "tier": 1}, {"id": "cert3-1.1-practice-1-1-1", "prompt": "Which concept best fits this description? Local frame delivery using link-layer addressing and media access.", "explanation": "Data link: Local frame delivery using link-layer addressing and media access. The other choices describe different mechanisms or properties.", "options": ["Physical", "Transport", "Data link", "Network"], "answer": 2, "tier": 1}, {"id": "cert3-1.1-match-1-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Physical: Bits carried as electrical, optical, or radio signals.\nData link: Local frame delivery using link-layer addressing and media access.\nNetwork: Logical addressing and routing between networks.\nTransport: End-to-end transport behavior such as TCP reliability or UDP datagrams.", "left": ["Physical", "Data link", "Network", "Transport"], "options": ["Logical addressing and routing between networks.", "Bits carried as electrical, optical, or radio signals.", "End-to-end transport behavior such as TCP reliability or UDP datagrams.", "Local frame delivery using link-layer addressing and media access."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.2", "title": "Choose the right network appliance", "core": 3, "objective": "1.2", "domain": 1, "type": "network", "requires": ["cert3-1.1"], "lore": "Separate forwarding, routing, security, and application mediation. A device may combine functions, so identify the behavior required by the scenario.\n\nYOUR TOOLKIT\n\nSwitch — Forwards frames within a local switched network using a MAC address table.\n\nRouter — Forwards packets between IP networks according to a routing table.\n\nProxy — Mediates client requests at an application-aware intermediary.\n\nLoad balancer — Distributes connections or requests among available service instances.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Two VLANs must communicate under policy. Use a routing function with access enforcement rather than an unmanaged hub.", "questions": [{"id": "cert3-1.2-practice-1-2-0", "prompt": "Which concept best fits this description? Forwards frames within a local switched network using a MAC address table.", "explanation": "Switch: Forwards frames within a local switched network using a MAC address table. The other choices describe different mechanisms or properties.", "options": ["Router", "Load balancer", "Proxy", "Switch"], "answer": 3, "tier": 1}, {"id": "cert3-1.2-practice-1-2-1", "prompt": "Which concept best fits this description? Forwards packets between IP networks according to a routing table.", "explanation": "Router: Forwards packets between IP networks according to a routing table. The other choices describe different mechanisms or properties.", "options": ["Switch", "Load balancer", "Router", "Proxy"], "answer": 2, "tier": 1}, {"id": "cert3-1.2-match-1-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Switch: Forwards frames within a local switched network using a MAC address table.\nRouter: Forwards packets between IP networks according to a routing table.\nProxy: Mediates client requests at an application-aware intermediary.\nLoad balancer: Distributes connections or requests among available service instances.", "left": ["Switch", "Router", "Proxy", "Load balancer"], "options": ["Mediates client requests at an application-aware intermediary.", "Forwards frames within a local switched network using a MAC address table.", "Distributes connections or requests among available service instances.", "Forwards packets between IP networks according to a routing table."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.3", "title": "Connect cloud networks deliberately", "core": 3, "objective": "1.3", "domain": 1, "type": "network", "requires": ["cert3-1.2"], "lore": "Cloud connectivity still needs routing, address planning, identity, segmentation, and monitoring. A private circuit and an encrypted tunnel solve different problems.\n\nYOUR TOOLKIT\n\nVirtual private cloud — A logically isolated cloud networking environment with customer-defined subnets and routes.\n\nSite-to-site VPN — A protected network tunnel connecting two network locations over another network.\n\nPrivate connectivity — A dedicated or provider-managed private route to cloud resources rather than ordinary public internet transit.\n\nSecurity group — A cloud resource traffic policy whose exact statefulness and scope depend on the provider.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A private cloud subnet needs outbound updates without accepting unsolicited inbound internet connections. Evaluate a suitable egress design and narrow rules.", "questions": [{"id": "cert3-1.3-practice-1-3-0", "prompt": "Which concept best fits this description? A logically isolated cloud networking environment with customer-defined subnets and routes.", "explanation": "Virtual private cloud: A logically isolated cloud networking environment with customer-defined subnets and routes. The other choices describe different mechanisms or properties.", "options": ["Site-to-site VPN", "Security group", "Private connectivity", "Virtual private cloud"], "answer": 3, "tier": 1}, {"id": "cert3-1.3-practice-1-3-1", "prompt": "Which concept best fits this description? A protected network tunnel connecting two network locations over another network.", "explanation": "Site-to-site VPN: A protected network tunnel connecting two network locations over another network. The other choices describe different mechanisms or properties.", "options": ["Virtual private cloud", "Security group", "Site-to-site VPN", "Private connectivity"], "answer": 2, "tier": 1}, {"id": "cert3-1.3-match-1-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Virtual private cloud: A logically isolated cloud networking environment with customer-defined subnets and routes.\nSite-to-site VPN: A protected network tunnel connecting two network locations over another network.\nPrivate connectivity: A dedicated or provider-managed private route to cloud resources rather than ordinary public internet transit.\nSecurity group: A cloud resource traffic policy whose exact statefulness and scope depend on the provider.", "left": ["Virtual private cloud", "Site-to-site VPN", "Private connectivity", "Security group"], "options": ["A dedicated or provider-managed private route to cloud resources rather than ordinary public internet transit.", "A logically isolated cloud networking environment with customer-defined subnets and routes.", "A cloud resource traffic policy whose exact statefulness and scope depend on the provider.", "A protected network tunnel connecting two network locations over another network."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.4", "title": "Read protocols, ports, and traffic", "core": 3, "objective": "1.4", "domain": 1, "type": "network", "requires": ["cert3-1.3"], "lore": "Ports identify transport endpoints, not proof of a trustworthy application. Learn common defaults and verify actual configuration. TCP supplies ordered reliable byte delivery, while UDP supplies datagrams without that guarantee.\n\nYOUR TOOLKIT\n\nTCP — A connection-oriented transport providing ordered reliable byte delivery.\n\nUDP — A connectionless datagram transport without built-in delivery or ordering guarantees.\n\nDNS — Name-resolution service commonly using UDP53 and TCP53 depending on operation.\n\nHTTPS — HTTP protected by TLS, commonly reached using TCP443.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A name resolves but the secure website is unreachable. Test the intended TCP443 path and TLS service instead of assuming DNS remains the fault.", "questions": [{"id": "cert3-1.4-practice-1-4-0", "prompt": "Which concept best fits this description? A connection-oriented transport providing ordered reliable byte delivery.", "explanation": "TCP: A connection-oriented transport providing ordered reliable byte delivery. The other choices describe different mechanisms or properties.", "options": ["UDP", "HTTPS", "DNS", "TCP"], "answer": 3, "tier": 1}, {"id": "cert3-1.4-practice-1-4-1", "prompt": "Which concept best fits this description? A connectionless datagram transport without built-in delivery or ordering guarantees.", "explanation": "UDP: A connectionless datagram transport without built-in delivery or ordering guarantees. The other choices describe different mechanisms or properties.", "options": ["TCP", "HTTPS", "UDP", "DNS"], "answer": 2, "tier": 1}, {"id": "cert3-1.4-match-1-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "TCP: A connection-oriented transport providing ordered reliable byte delivery.\nUDP: A connectionless datagram transport without built-in delivery or ordering guarantees.\nDNS: Name-resolution service commonly using UDP53 and TCP53 depending on operation.\nHTTPS: HTTP protected by TLS, commonly reached using TCP443.", "left": ["TCP", "UDP", "DNS", "HTTPS"], "options": ["Name-resolution service commonly using UDP53 and TCP53 depending on operation.", "A connection-oriented transport providing ordered reliable byte delivery.", "HTTP protected by TLS, commonly reached using TCP443.", "A connectionless datagram transport without built-in delivery or ordering guarantees."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.5", "title": "Match the medium to the requirement", "core": 3, "objective": "1.5", "domain": 1, "type": "network", "requires": ["cert3-1.4"], "lore": "Distance, bandwidth, interference, connector type, and optical characteristics determine the right link. Match both ends and never look into an active fiber connector.\n\nYOUR TOOLKIT\n\nSingle-mode fiber — Optical media using a small core for long-distance links with matched optics.\n\nMultimode fiber — Optical media commonly used for shorter links with compatible wavelengths and transceivers.\n\nTwisted-pair copper — Balanced copper pairs used for many Ethernet links with category and distance limits.\n\nTransceiver compatibility — Matching speed, wavelength, fiber type, connector, and platform support at both ends.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A long interbuilding link crosses an electrically noisy area. Fiber avoids electrical interference and conductive building-to-building paths.", "questions": [{"id": "cert3-1.5-practice-1-5-0", "prompt": "Which concept best fits this description? Optical media using a small core for long-distance links with matched optics.", "explanation": "Single-mode fiber: Optical media using a small core for long-distance links with matched optics. The other choices describe different mechanisms or properties.", "options": ["Multimode fiber", "Transceiver compatibility", "Twisted-pair copper", "Single-mode fiber"], "answer": 3, "tier": 1}, {"id": "cert3-1.5-practice-1-5-1", "prompt": "Which concept best fits this description? Optical media commonly used for shorter links with compatible wavelengths and transceivers.", "explanation": "Multimode fiber: Optical media commonly used for shorter links with compatible wavelengths and transceivers. The other choices describe different mechanisms or properties.", "options": ["Single-mode fiber", "Transceiver compatibility", "Multimode fiber", "Twisted-pair copper"], "answer": 2, "tier": 1}, {"id": "cert3-1.5-match-1-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Single-mode fiber: Optical media using a small core for long-distance links with matched optics.\nMultimode fiber: Optical media commonly used for shorter links with compatible wavelengths and transceivers.\nTwisted-pair copper: Balanced copper pairs used for many Ethernet links with category and distance limits.\nTransceiver compatibility: Matching speed, wavelength, fiber type, connector, and platform support at both ends.", "left": ["Single-mode fiber", "Multimode fiber", "Twisted-pair copper", "Transceiver compatibility"], "options": ["Balanced copper pairs used for many Ethernet links with category and distance limits.", "Optical media using a small core for long-distance links with matched optics.", "Matching speed, wavelength, fiber type, connector, and platform support at both ends.", "Optical media commonly used for shorter links with compatible wavelengths and transceivers."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.6", "title": "Map the topology and failure paths", "core": 3, "objective": "1.6", "domain": 1, "type": "network", "requires": ["cert3-1.5"], "lore": "A topology affects scale, cost, and failure domains. Distinguish physical layout from logical connectivity and identify where redundancy really exists.\n\nYOUR TOOLKIT\n\nStar topology — Endpoints connect through a central device whose failure can affect many peers.\n\nMesh topology — Nodes have multiple interconnections that can provide alternate paths at additional cost.\n\nSpine-leaf architecture — A fabric in which leaves connect to spines to support predictable east-west connectivity.\n\nThree-tier architecture — A network organized into access, distribution, and core roles.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Two uplinks share the same conduit. They improve some device failures but do not survive the same cable cut.", "questions": [{"id": "cert3-1.6-practice-1-6-0", "prompt": "Which concept best fits this description? Endpoints connect through a central device whose failure can affect many peers.", "explanation": "Star topology: Endpoints connect through a central device whose failure can affect many peers. The other choices describe different mechanisms or properties.", "options": ["Mesh topology", "Three-tier architecture", "Spine-leaf architecture", "Star topology"], "answer": 3, "tier": 1}, {"id": "cert3-1.6-practice-1-6-1", "prompt": "Which concept best fits this description? Nodes have multiple interconnections that can provide alternate paths at additional cost.", "explanation": "Mesh topology: Nodes have multiple interconnections that can provide alternate paths at additional cost. The other choices describe different mechanisms or properties.", "options": ["Star topology", "Three-tier architecture", "Mesh topology", "Spine-leaf architecture"], "answer": 2, "tier": 1}, {"id": "cert3-1.6-match-1-6", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Star topology: Endpoints connect through a central device whose failure can affect many peers.\nMesh topology: Nodes have multiple interconnections that can provide alternate paths at additional cost.\nSpine-leaf architecture: A fabric in which leaves connect to spines to support predictable east-west connectivity.\nThree-tier architecture: A network organized into access, distribution, and core roles.", "left": ["Star topology", "Mesh topology", "Spine-leaf architecture", "Three-tier architecture"], "options": ["A fabric in which leaves connect to spines to support predictable east-west connectivity.", "Endpoints connect through a central device whose failure can affect many peers.", "A network organized into access, distribution, and core roles.", "Nodes have multiple interconnections that can provide alternate paths at additional cost."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.7", "title": "Work out an IPv4 subnet", "core": 3, "objective": "1.7", "domain": 1, "type": "network", "requires": ["cert3-1.6"], "lore": "The prefix separates network bits from host bits. Determine the network, usable range, and broadcast before assigning an address. A traditional /24 contains 256 addresses with 254 usual host addresses.\n\nYOUR TOOLKIT\n\nCIDR prefix — A slash-length notation identifying the number of network bits in an IP address.\n\nPrivate IPv4 space — Address ranges 10/8, 172.16/12, and 192.168/16 intended for private use.\n\nAPIPA — IPv4 link-local addressing in 169.254/16, often seen when a client cannot obtain DHCP configuration.\n\nDefault gateway — The next-hop router a host uses for destinations outside its local subnet.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "192.0.2.70/26 lies in 192.0.2.64 through 192.0.2.127. The ordinary usable host range is .65 through .126. Do not assign the network or broadcast address to an ordinary host.", "questions": [{"id": "cert3-1.7-practice-1-7-0", "prompt": "Which concept best fits this description? A slash-length notation identifying the number of network bits in an IP address.", "explanation": "CIDR prefix: A slash-length notation identifying the number of network bits in an IP address. The other choices describe different mechanisms or properties.", "options": ["Private IPv4 space", "Default gateway", "APIPA", "CIDR prefix"], "answer": 3, "tier": 1}, {"id": "cert3-1.7-practice-1-7-1", "prompt": "Which concept best fits this description? Address ranges 10/8, 172.16/12, and 192.168/16 intended for private use.", "explanation": "Private IPv4 space: Address ranges 10/8, 172.16/12, and 192.168/16 intended for private use. The other choices describe different mechanisms or properties.", "options": ["CIDR prefix", "Default gateway", "Private IPv4 space", "APIPA"], "answer": 2, "tier": 1}, {"id": "cert3-1.7-match-1-7", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "CIDR prefix: A slash-length notation identifying the number of network bits in an IP address.\nPrivate IPv4 space: Address ranges 10/8, 172.16/12, and 192.168/16 intended for private use.\nAPIPA: IPv4 link-local addressing in 169.254/16, often seen when a client cannot obtain DHCP configuration.\nDefault gateway: The next-hop router a host uses for destinations outside its local subnet.", "left": ["CIDR prefix", "Private IPv4 space", "APIPA", "Default gateway"], "options": ["IPv4 link-local addressing in 169.254/16, often seen when a client cannot obtain DHCP configuration.", "A slash-length notation identifying the number of network bits in an IP address.", "The next-hop router a host uses for destinations outside its local subnet.", "Address ranges 10/8, 172.16/12, and 192.168/16 intended for private use."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert3-1.7-scenario-1-7-0", "prompt": "Host 192.0.2.70/26 needs a valid gateway in its local subnet.\n\nWhich network contains the host?", "explanation": "/26 boundaries occur every 64 addresses; .70 lies in .64 through .127.", "options": ["192.0.2.0/26", "192.0.2.64/26", "192.0.2.128/26"], "answer": 1, "tier": 3}, {"id": "cert3-1.7-scenario-1-7-1", "prompt": "Host 192.0.2.70/26 needs a valid gateway in its local subnet.\n\nWhich address is an ordinary valid gateway candidate in that subnet?", "explanation": ".64 is the network address and .127 the broadcast; .65 is a usable host address.", "options": ["192.0.2.64", "192.0.2.127", "192.0.2.65"], "answer": 2, "tier": 3}, {"id": "cert3-1.7-scenario-1-7-2", "prompt": "Host 192.0.2.70/26 needs a valid gateway in its local subnet.\n\nHow many ordinary host addresses are in this /26?", "explanation": "Six host bits give 64 total addresses, normally 62 usable hosts.", "options": ["62", "64", "254"], "answer": 0, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-1.8", "title": "Understand modern network control", "core": 3, "objective": "1.8", "domain": 1, "type": "network", "requires": ["cert3-1.7"], "lore": "Modern designs separate intent, policy, and forwarding. Automation improves consistency only when templates and controller privileges are controlled.\n\nYOUR TOOLKIT\n\nSoftware-defined networking — Separating programmable network control from underlying packet forwarding.\n\nSD-WAN — Policy-driven WAN connectivity that can select among paths according to application and link conditions.\n\nVXLAN — An overlay encapsulation that extends logical layer-two segments across an IP underlay.\n\nInfrastructure as code — Versioned machine-readable definitions used to provision and manage infrastructure.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A branch needs application-aware path selection across two carriers. Compare SD-WAN behavior rather than assuming a second cable alone selects the best application path.", "questions": [{"id": "cert3-1.8-practice-1-8-0", "prompt": "Which concept best fits this description? Separating programmable network control from underlying packet forwarding.", "explanation": "Software-defined networking: Separating programmable network control from underlying packet forwarding. The other choices describe different mechanisms or properties.", "options": ["SD-WAN", "Infrastructure as code", "VXLAN", "Software-defined networking"], "answer": 3, "tier": 1}, {"id": "cert3-1.8-practice-1-8-1", "prompt": "Which concept best fits this description? Policy-driven WAN connectivity that can select among paths according to application and link conditions.", "explanation": "SD-WAN: Policy-driven WAN connectivity that can select among paths according to application and link conditions. The other choices describe different mechanisms or properties.", "options": ["Software-defined networking", "Infrastructure as code", "SD-WAN", "VXLAN"], "answer": 2, "tier": 1}, {"id": "cert3-1.8-match-1-8", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Software-defined networking: Separating programmable network control from underlying packet forwarding.\nSD-WAN: Policy-driven WAN connectivity that can select among paths according to application and link conditions.\nVXLAN: An overlay encapsulation that extends logical layer-two segments across an IP underlay.\nInfrastructure as code: Versioned machine-readable definitions used to provision and manage infrastructure.", "left": ["Software-defined networking", "SD-WAN", "VXLAN", "Infrastructure as code"], "options": ["An overlay encapsulation that extends logical layer-two segments across an IP underlay.", "Separating programmable network control from underlying packet forwarding.", "Versioned machine-readable definitions used to provision and manage infrastructure.", "Policy-driven WAN connectivity that can select among paths according to application and link conditions."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-2.1", "title": "Choose a route", "core": 3, "objective": "2.1", "domain": 2, "type": "network", "requires": [], "lore": "A router selects a matching route before forwarding. Longest-prefix matching chooses the most specific applicable network. Metrics and administrative preference resolve other route-selection decisions within platform rules.\n\nYOUR TOOLKIT\n\nStatic route — A route explicitly configured by an administrator.\n\nDynamic routing — Learning and updating reachability through a routing protocol.\n\nLongest-prefix match — Selecting the valid route with the most specific matching destination prefix.\n\nNAT — Translating network addresses, often with port translation to share public connectivity.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A router has 0.0.0.0/0 and 192.0.2.0/24. Traffic to 192.0.2.9 uses the /24 when both are valid.", "questions": [{"id": "cert3-2.1-practice-2-1-0", "prompt": "Which concept best fits this description? A route explicitly configured by an administrator.", "explanation": "Static route: A route explicitly configured by an administrator. The other choices describe different mechanisms or properties.", "options": ["NAT", "Longest-prefix match", "Static route", "Dynamic routing"], "answer": 2, "tier": 1}, {"id": "cert3-2.1-practice-2-1-1", "prompt": "Which concept best fits this description? Learning and updating reachability through a routing protocol.", "explanation": "Dynamic routing: Learning and updating reachability through a routing protocol. The other choices describe different mechanisms or properties.", "options": ["NAT", "Dynamic routing", "Longest-prefix match", "Static route"], "answer": 1, "tier": 1}, {"id": "cert3-2.1-match-2-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Static route: A route explicitly configured by an administrator.\nDynamic routing: Learning and updating reachability through a routing protocol.\nLongest-prefix match: Selecting the valid route with the most specific matching destination prefix.\nNAT: Translating network addresses, often with port translation to share public connectivity.", "left": ["Static route", "Dynamic routing", "Longest-prefix match", "NAT"], "options": ["Selecting the valid route with the most specific matching destination prefix.", "A route explicitly configured by an administrator.", "Translating network addresses, often with port translation to share public connectivity.", "Learning and updating reachability through a routing protocol."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-2.2", "title": "Build a switched network", "core": 3, "objective": "2.2", "domain": 2, "type": "network", "requires": ["cert3-2.1"], "lore": "VLANs separate broadcast domains but do not automatically enforce all security policy. Trunks carry multiple VLANs and spanning tree prevents certain layer-two forwarding loops.\n\nYOUR TOOLKIT\n\nAccess port — A switch port configured for endpoint membership in an access VLAN.\n\nVLAN trunk — A link carrying multiple VLANs using agreed tagging and allowed-VLAN settings.\n\nSpanning Tree Protocol — A mechanism that blocks selected redundant layer-two paths to prevent forwarding loops.\n\nLink aggregation — Combining compatible physical links into a logical bundle for capacity or redundancy.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A workstation receives the wrong department subnet. Check the access port VLAN and upstream trunk before replacing the workstation.", "questions": [{"id": "cert3-2.2-practice-2-2-0", "prompt": "Which concept best fits this description? A switch port configured for endpoint membership in an access VLAN.", "explanation": "Access port: A switch port configured for endpoint membership in an access VLAN. The other choices describe different mechanisms or properties.", "options": ["Link aggregation", "Spanning Tree Protocol", "Access port", "VLAN trunk"], "answer": 2, "tier": 1}, {"id": "cert3-2.2-practice-2-2-1", "prompt": "Which concept best fits this description? A link carrying multiple VLANs using agreed tagging and allowed-VLAN settings.", "explanation": "VLAN trunk: A link carrying multiple VLANs using agreed tagging and allowed-VLAN settings. The other choices describe different mechanisms or properties.", "options": ["Link aggregation", "VLAN trunk", "Spanning Tree Protocol", "Access port"], "answer": 1, "tier": 1}, {"id": "cert3-2.2-match-2-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Access port: A switch port configured for endpoint membership in an access VLAN.\nVLAN trunk: A link carrying multiple VLANs using agreed tagging and allowed-VLAN settings.\nSpanning Tree Protocol: A mechanism that blocks selected redundant layer-two paths to prevent forwarding loops.\nLink aggregation: Combining compatible physical links into a logical bundle for capacity or redundancy.", "left": ["Access port", "VLAN trunk", "Spanning Tree Protocol", "Link aggregation"], "options": ["A mechanism that blocks selected redundant layer-two paths to prevent forwarding loops.", "A switch port configured for endpoint membership in an access VLAN.", "Combining compatible physical links into a logical bundle for capacity or redundancy.", "A link carrying multiple VLANs using agreed tagging and allowed-VLAN settings."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert3-2.2-scenario-2-2-0", "prompt": "A wired finance workstation gets a guest-network address. Other finance users on the correct VLAN work.\n\nWhat should you inspect first?", "explanation": "The assigned subnet suggests the endpoint is attached to the wrong logical segment.", "options": ["The workstation's access-port VLAN and patch path", "Every public DNS root server", "The printer toner"], "answer": 0, "tier": 3}, {"id": "cert3-2.2-scenario-2-2-1", "prompt": "A wired finance workstation gets a guest-network address. Other finance users on the correct VLAN work.\n\nWhat should a fix verification include?", "explanation": "Verify intended functionality and boundaries after changing VLAN membership.", "options": ["Only the link LED", "Correct address, required finance access, and guest isolation", "A new wallpaper"], "answer": 1, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-2.3", "title": "Tune wireless for the environment", "core": 3, "objective": "2.3", "domain": 2, "type": "network", "requires": ["cert3-2.2"], "lore": "Channel use, interference, signal strength, roaming, density, and authentication all influence wireless service. More transmit power is not always better.\n\nYOUR TOOLKIT\n\nSSID — The advertised or configured wireless network name.\n\nChannel planning — Selecting channels and widths to manage overlap, interference, and capacity.\n\nEnterprise wireless authentication — Per-user or per-device authentication commonly using 802.1X and a RADIUS-backed identity system.\n\nSite survey — Measuring coverage and interference to plan or validate wireless deployment.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Clients hear the AP but cannot transmit reliably back to it. Increasing only AP power may worsen asymmetric coverage.", "questions": [{"id": "cert3-2.3-practice-2-3-0", "prompt": "Which concept best fits this description? The advertised or configured wireless network name.", "explanation": "SSID: The advertised or configured wireless network name. The other choices describe different mechanisms or properties.", "options": ["Site survey", "Enterprise wireless authentication", "SSID", "Channel planning"], "answer": 2, "tier": 1}, {"id": "cert3-2.3-practice-2-3-1", "prompt": "Which concept best fits this description? Selecting channels and widths to manage overlap, interference, and capacity.", "explanation": "Channel planning: Selecting channels and widths to manage overlap, interference, and capacity. The other choices describe different mechanisms or properties.", "options": ["Site survey", "Channel planning", "Enterprise wireless authentication", "SSID"], "answer": 1, "tier": 1}, {"id": "cert3-2.3-match-2-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "SSID: The advertised or configured wireless network name.\nChannel planning: Selecting channels and widths to manage overlap, interference, and capacity.\nEnterprise wireless authentication: Per-user or per-device authentication commonly using 802.1X and a RADIUS-backed identity system.\nSite survey: Measuring coverage and interference to plan or validate wireless deployment.", "left": ["SSID", "Channel planning", "Enterprise wireless authentication", "Site survey"], "options": ["Per-user or per-device authentication commonly using 802.1X and a RADIUS-backed identity system.", "The advertised or configured wireless network name.", "Measuring coverage and interference to plan or validate wireless deployment.", "Selecting channels and widths to manage overlap, interference, and capacity."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-2.4", "title": "Install with safety and resilience", "core": 3, "objective": "2.4", "domain": 2, "type": "network", "requires": ["cert3-2.3"], "lore": "Rack layout, power, cable management, airflow, grounding, and labeling influence reliability. Follow equipment ratings and local safety requirements.\n\nYOUR TOOLKIT\n\nPatch panel — A structured termination point connecting permanent cabling to replaceable patch leads.\n\nUPS — Battery-backed power that bridges interruptions and supports controlled shutdown.\n\nPoE budget — The total and per-port electrical power a switch can safely supply to attached devices.\n\nEnvironmental monitoring — Tracking conditions such as temperature and humidity to detect risks to equipment.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A new switch blocks another device's exhaust. Correct airflow before treating rising temperatures as a software problem.", "questions": [{"id": "cert3-2.4-practice-2-4-0", "prompt": "Which concept best fits this description? A structured termination point connecting permanent cabling to replaceable patch leads.", "explanation": "Patch panel: A structured termination point connecting permanent cabling to replaceable patch leads. The other choices describe different mechanisms or properties.", "options": ["Environmental monitoring", "PoE budget", "Patch panel", "UPS"], "answer": 2, "tier": 1}, {"id": "cert3-2.4-practice-2-4-1", "prompt": "Which concept best fits this description? Battery-backed power that bridges interruptions and supports controlled shutdown.", "explanation": "UPS: Battery-backed power that bridges interruptions and supports controlled shutdown. The other choices describe different mechanisms or properties.", "options": ["Environmental monitoring", "UPS", "PoE budget", "Patch panel"], "answer": 1, "tier": 1}, {"id": "cert3-2.4-match-2-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Patch panel: A structured termination point connecting permanent cabling to replaceable patch leads.\nUPS: Battery-backed power that bridges interruptions and supports controlled shutdown.\nPoE budget: The total and per-port electrical power a switch can safely supply to attached devices.\nEnvironmental monitoring: Tracking conditions such as temperature and humidity to detect risks to equipment.", "left": ["Patch panel", "UPS", "PoE budget", "Environmental monitoring"], "options": ["The total and per-port electrical power a switch can safely supply to attached devices.", "A structured termination point connecting permanent cabling to replaceable patch leads.", "Tracking conditions such as temperature and humidity to detect risks to equipment.", "Battery-backed power that bridges interruptions and supports controlled shutdown."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-3.1", "title": "Keep useful operational records", "core": 3, "objective": "3.1", "domain": 3, "type": "network", "requires": [], "lore": "Documentation must describe the actual network. Maintain diagrams, address assignments, asset records, configurations, change history, and recovery instructions.\n\nYOUR TOOLKIT\n\nIP address management — Maintaining records of address spaces, assignments, and related network configuration.\n\nConfiguration backup — A recoverable copy of device settings taken and tested under controlled procedures.\n\nChange management — Assessing, authorizing, executing, and verifying modifications with accountable records.\n\nLogical diagram — A representation of network relationships and traffic structure rather than only physical rack placement.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A remote engineer must restore a switch after failure. A current versioned configuration and port map are more useful than an obsolete shopping list.", "questions": [{"id": "cert3-3.1-practice-3-1-0", "prompt": "Which concept best fits this description? Maintaining records of address spaces, assignments, and related network configuration.", "explanation": "IP address management: Maintaining records of address spaces, assignments, and related network configuration. The other choices describe different mechanisms or properties.", "options": ["Change management", "IP address management", "Configuration backup", "Logical diagram"], "answer": 1, "tier": 1}, {"id": "cert3-3.1-practice-3-1-1", "prompt": "Which concept best fits this description? A recoverable copy of device settings taken and tested under controlled procedures.", "explanation": "Configuration backup: A recoverable copy of device settings taken and tested under controlled procedures. The other choices describe different mechanisms or properties.", "options": ["Configuration backup", "Change management", "IP address management", "Logical diagram"], "answer": 0, "tier": 1}, {"id": "cert3-3.1-match-3-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "IP address management: Maintaining records of address spaces, assignments, and related network configuration.\nConfiguration backup: A recoverable copy of device settings taken and tested under controlled procedures.\nChange management: Assessing, authorizing, executing, and verifying modifications with accountable records.\nLogical diagram: A representation of network relationships and traffic structure rather than only physical rack placement.", "left": ["IP address management", "Configuration backup", "Change management", "Logical diagram"], "options": ["Assessing, authorizing, executing, and verifying modifications with accountable records.", "Maintaining records of address spaces, assignments, and related network configuration.", "A representation of network relationships and traffic structure rather than only physical rack placement.", "A recoverable copy of device settings taken and tested under controlled procedures."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-3.2", "title": "Monitor what matters", "core": 3, "objective": "3.2", "domain": 3, "type": "network", "requires": ["cert3-3.1"], "lore": "Combine availability, utilization, errors, latency, logs, and flow data. Establish a baseline so an alert reflects an important deviation rather than arbitrary noise.\n\nYOUR TOOLKIT\n\nSNMP — A network management protocol used to obtain device information and, where permitted, change settings.\n\nSyslog — A mechanism for transmitting event messages to a logging service.\n\nFlow telemetry — Communication metadata used to analyze endpoints, volume, timing, and patterns.\n\nBaseline — Recorded expected behavior used to compare current measurements.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A link reports high utilization every weekday at backup time. Check whether service performance is affected before calling the pattern an incident.", "questions": [{"id": "cert3-3.2-practice-3-2-0", "prompt": "Which concept best fits this description? A network management protocol used to obtain device information and, where permitted, change settings.", "explanation": "SNMP: A network management protocol used to obtain device information and, where permitted, change settings. The other choices describe different mechanisms or properties.", "options": ["Flow telemetry", "SNMP", "Syslog", "Baseline"], "answer": 1, "tier": 1}, {"id": "cert3-3.2-practice-3-2-1", "prompt": "Which concept best fits this description? A mechanism for transmitting event messages to a logging service.", "explanation": "Syslog: A mechanism for transmitting event messages to a logging service. The other choices describe different mechanisms or properties.", "options": ["Syslog", "Flow telemetry", "SNMP", "Baseline"], "answer": 0, "tier": 1}, {"id": "cert3-3.2-match-3-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "SNMP: A network management protocol used to obtain device information and, where permitted, change settings.\nSyslog: A mechanism for transmitting event messages to a logging service.\nFlow telemetry: Communication metadata used to analyze endpoints, volume, timing, and patterns.\nBaseline: Recorded expected behavior used to compare current measurements.", "left": ["SNMP", "Syslog", "Flow telemetry", "Baseline"], "options": ["Communication metadata used to analyze endpoints, volume, timing, and patterns.", "A network management protocol used to obtain device information and, where permitted, change settings.", "Recorded expected behavior used to compare current measurements.", "A mechanism for transmitting event messages to a logging service."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-3.3", "title": "Recover network services", "core": 3, "objective": "3.3", "domain": 3, "type": "network", "requires": ["cert3-3.2"], "lore": "Redundant equipment is only useful when dependencies and failover behavior are understood. Test recovery against business requirements rather than relying on a green status light.\n\nYOUR TOOLKIT\n\nRTO — A target time for restoring a disrupted service.\n\nRPO — The tolerable data-loss window measured in time.\n\nFailover test — A controlled exercise proving a backup path or component actually takes over.\n\nRecovery dependency — A supporting service such as DNS, power, or identity needed for successful restoration.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Both routers depend on one power feed. A second router does not remove the shared power failure.", "questions": [{"id": "cert3-3.3-practice-3-3-0", "prompt": "Which concept best fits this description? A target time for restoring a disrupted service.", "explanation": "RTO: A target time for restoring a disrupted service. The other choices describe different mechanisms or properties.", "options": ["Failover test", "RTO", "RPO", "Recovery dependency"], "answer": 1, "tier": 1}, {"id": "cert3-3.3-practice-3-3-1", "prompt": "Which concept best fits this description? The tolerable data-loss window measured in time.", "explanation": "RPO: The tolerable data-loss window measured in time. The other choices describe different mechanisms or properties.", "options": ["RPO", "Failover test", "RTO", "Recovery dependency"], "answer": 0, "tier": 1}, {"id": "cert3-3.3-match-3-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "RTO: A target time for restoring a disrupted service.\nRPO: The tolerable data-loss window measured in time.\nFailover test: A controlled exercise proving a backup path or component actually takes over.\nRecovery dependency: A supporting service such as DNS, power, or identity needed for successful restoration.", "left": ["RTO", "RPO", "Failover test", "Recovery dependency"], "options": ["A controlled exercise proving a backup path or component actually takes over.", "A target time for restoring a disrupted service.", "A supporting service such as DNS, power, or identity needed for successful restoration.", "The tolerable data-loss window measured in time."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-3.4", "title": "Deliver network configuration and names", "core": 3, "objective": "3.4", "domain": 3, "type": "network", "requires": ["cert3-3.3"], "lore": "DHCP, DNS, and time services underpin many applications. Separate address assignment from name resolution, and distinguish IPv4 behavior from IPv6 mechanisms.\n\nYOUR TOOLKIT\n\nDHCP — A service that leases IP configuration to clients.\n\nDNS A record — A record mapping a hostname to an IPv4 address.\n\nDNS AAAA record — A record mapping a hostname to an IPv6 address.\n\nSLAAC — IPv6 host address configuration using router advertisements and local address-generation behavior.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A client can reach a server by IP but not by hostname. Investigate name resolution and configured DNS rather than assuming the cable is broken.", "questions": [{"id": "cert3-3.4-practice-3-4-0", "prompt": "Which concept best fits this description? A service that leases IP configuration to clients.", "explanation": "DHCP: A service that leases IP configuration to clients. The other choices describe different mechanisms or properties.", "options": ["DNS AAAA record", "DHCP", "DNS A record", "SLAAC"], "answer": 1, "tier": 1}, {"id": "cert3-3.4-practice-3-4-1", "prompt": "Which concept best fits this description? A record mapping a hostname to an IPv4 address.", "explanation": "DNS A record: A record mapping a hostname to an IPv4 address. The other choices describe different mechanisms or properties.", "options": ["DNS A record", "DNS AAAA record", "DHCP", "SLAAC"], "answer": 0, "tier": 1}, {"id": "cert3-3.4-match-3-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "DHCP: A service that leases IP configuration to clients.\nDNS A record: A record mapping a hostname to an IPv4 address.\nDNS AAAA record: A record mapping a hostname to an IPv6 address.\nSLAAC: IPv6 host address configuration using router advertisements and local address-generation behavior.", "left": ["DHCP", "DNS A record", "DNS AAAA record", "SLAAC"], "options": ["A record mapping a hostname to an IPv6 address.", "A service that leases IP configuration to clients.", "IPv6 host address configuration using router advertisements and local address-generation behavior.", "A record mapping a hostname to an IPv4 address."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert3-3.4-scenario-3-4-0", "prompt": "A client reaches 192.0.2.20 by IP. The same application fails when addressed by its expected hostname.\n\nWhich service is the most direct next investigation?", "explanation": "Working IP access with failed hostname access points toward resolution or name-dependent application configuration.", "options": ["The CPU cooler", "The rack fan", "DNS resolution"], "answer": 2, "tier": 3}, {"id": "cert3-3.4-scenario-3-4-1", "prompt": "A client reaches 192.0.2.20 by IP. The same application fails when addressed by its expected hostname.\n\nWhich observation would support a resolver problem?", "explanation": "A targeted lookup tests the name-resolution path.", "options": ["A lookup against the configured resolver returns failure for a known valid record", "The Ethernet cable is blue", "The monitor uses HDMI"], "answer": 0, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-3.5", "title": "Manage through a controlled path", "core": 3, "objective": "3.5", "domain": 3, "type": "network", "requires": ["cert3-3.4"], "lore": "Use encrypted administration, limited source access, accountable identities, and recoverable out-of-band options. A VPN tunnel does not justify unrestricted administrator authority.\n\nYOUR TOOLKIT\n\nSSH — An encrypted protocol commonly used for remote command-line administration.\n\nOut-of-band management — A management path separate from the normal production data path.\n\nConsole access — Direct or mediated access to a device's local administrative interface.\n\nJump host — A controlled intermediary used to constrain and audit administrative connections.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A bad route removes in-band reachability. A secured console or separate management path may allow repair.", "questions": [{"id": "cert3-3.5-practice-3-5-0", "prompt": "Which concept best fits this description? An encrypted protocol commonly used for remote command-line administration.", "explanation": "SSH: An encrypted protocol commonly used for remote command-line administration. The other choices describe different mechanisms or properties.", "options": ["Console access", "SSH", "Out-of-band management", "Jump host"], "answer": 1, "tier": 1}, {"id": "cert3-3.5-practice-3-5-1", "prompt": "Which concept best fits this description? A management path separate from the normal production data path.", "explanation": "Out-of-band management: A management path separate from the normal production data path. The other choices describe different mechanisms or properties.", "options": ["Out-of-band management", "Console access", "SSH", "Jump host"], "answer": 0, "tier": 1}, {"id": "cert3-3.5-match-3-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "SSH: An encrypted protocol commonly used for remote command-line administration.\nOut-of-band management: A management path separate from the normal production data path.\nConsole access: Direct or mediated access to a device's local administrative interface.\nJump host: A controlled intermediary used to constrain and audit administrative connections.", "left": ["SSH", "Out-of-band management", "Console access", "Jump host"], "options": ["Direct or mediated access to a device's local administrative interface.", "An encrypted protocol commonly used for remote command-line administration.", "A controlled intermediary used to constrain and audit administrative connections.", "A management path separate from the normal production data path."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-4.1", "title": "Apply network security fundamentals", "core": 3, "objective": "4.1", "domain": 4, "type": "network", "requires": [], "lore": "Security combines access decisions, protected communication, monitoring, and governance. Verify identity and grant only required access rather than trusting network location alone.\n\nYOUR TOOLKIT\n\nLeast privilege — Providing only permissions needed for a defined task.\n\nAAA — Separate functions for authentication, authorization, and accounting.\n\nPKI — A system of certificates, trust relationships, and key management supporting public-key identity assurance.\n\nZero trust — Avoiding implicit trust based only on network location or ownership.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A contractor uses the guest network. Separate their access from internal administrative services even if their laptop connects successfully.", "questions": [{"id": "cert3-4.1-practice-4-1-0", "prompt": "Which concept best fits this description? Providing only permissions needed for a defined task.", "explanation": "Least privilege: Providing only permissions needed for a defined task. The other choices describe different mechanisms or properties.", "options": ["Least privilege", "AAA", "Zero trust", "PKI"], "answer": 0, "tier": 1}, {"id": "cert3-4.1-practice-4-1-1", "prompt": "Which concept best fits this description? Separate functions for authentication, authorization, and accounting.", "explanation": "AAA: Separate functions for authentication, authorization, and accounting. The other choices describe different mechanisms or properties.", "options": ["PKI", "Least privilege", "Zero trust", "AAA"], "answer": 3, "tier": 1}, {"id": "cert3-4.1-match-4-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Least privilege: Providing only permissions needed for a defined task.\nAAA: Separate functions for authentication, authorization, and accounting.\nPKI: A system of certificates, trust relationships, and key management supporting public-key identity assurance.\nZero trust: Avoiding implicit trust based only on network location or ownership.", "left": ["Least privilege", "AAA", "PKI", "Zero trust"], "options": ["A system of certificates, trust relationships, and key management supporting public-key identity assurance.", "Providing only permissions needed for a defined task.", "Avoiding implicit trust based only on network location or ownership.", "Separate functions for authentication, authorization, and accounting."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-4.2", "title": "Recognize network attack patterns", "core": 3, "objective": "4.2", "domain": 4, "type": "network", "requires": ["cert3-4.1"], "lore": "Interpret patterns using evidence and context. Denial of service, spoofing, rogue services, and on-path behavior require different responses.\n\nYOUR TOOLKIT\n\nRogue DHCP server — An unauthorized service distributing misleading or harmful IP configuration.\n\nARP spoofing — Sending misleading address-resolution information to redirect local IPv4 traffic.\n\nVLAN hopping — Attempting to cross intended VLAN isolation through configuration weaknesses or tagging abuse.\n\nEvil twin — A deceptive wireless access point imitating a legitimate network.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Clients receive an unexpected gateway after connecting. Check DHCP sources and switching protections rather than randomly changing application passwords.", "questions": [{"id": "cert3-4.2-practice-4-2-0", "prompt": "Which concept best fits this description? An unauthorized service distributing misleading or harmful IP configuration.", "explanation": "Rogue DHCP server: An unauthorized service distributing misleading or harmful IP configuration. The other choices describe different mechanisms or properties.", "options": ["Rogue DHCP server", "ARP spoofing", "Evil twin", "VLAN hopping"], "answer": 0, "tier": 1}, {"id": "cert3-4.2-practice-4-2-1", "prompt": "Which concept best fits this description? Sending misleading address-resolution information to redirect local IPv4 traffic.", "explanation": "ARP spoofing: Sending misleading address-resolution information to redirect local IPv4 traffic. The other choices describe different mechanisms or properties.", "options": ["VLAN hopping", "Rogue DHCP server", "Evil twin", "ARP spoofing"], "answer": 3, "tier": 1}, {"id": "cert3-4.2-match-4-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Rogue DHCP server: An unauthorized service distributing misleading or harmful IP configuration.\nARP spoofing: Sending misleading address-resolution information to redirect local IPv4 traffic.\nVLAN hopping: Attempting to cross intended VLAN isolation through configuration weaknesses or tagging abuse.\nEvil twin: A deceptive wireless access point imitating a legitimate network.", "left": ["Rogue DHCP server", "ARP spoofing", "VLAN hopping", "Evil twin"], "options": ["Attempting to cross intended VLAN isolation through configuration weaknesses or tagging abuse.", "An unauthorized service distributing misleading or harmful IP configuration.", "A deceptive wireless access point imitating a legitimate network.", "Sending misleading address-resolution information to redirect local IPv4 traffic."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-4.3", "title": "Enforce network defenses", "core": 3, "objective": "4.3", "domain": 4, "type": "network", "requires": ["cert3-4.2"], "lore": "Place controls at the boundary they protect and verify both permitted and forbidden traffic. Segment vulnerable devices and protect administration separately.\n\nYOUR TOOLKIT\n\nACL — A configured set of permit and deny rules for traffic or access.\n\n802.1X — Port-based access control using an authenticated supplicant and an authentication service.\n\nDHCP snooping — A switch feature that distinguishes trusted DHCP paths and helps reject unauthorized server responses.\n\nMicrosegmentation — Fine-grained controls limiting communication between workloads or small groups.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Only the web tier should reach the database. Enforce a specific source, destination, protocol, and port rule rather than relying on names.", "questions": [{"id": "cert3-4.3-practice-4-3-0", "prompt": "Which concept best fits this description? A configured set of permit and deny rules for traffic or access.", "explanation": "ACL: A configured set of permit and deny rules for traffic or access. The other choices describe different mechanisms or properties.", "options": ["ACL", "802.1X", "Microsegmentation", "DHCP snooping"], "answer": 0, "tier": 1}, {"id": "cert3-4.3-practice-4-3-1", "prompt": "Which concept best fits this description? Port-based access control using an authenticated supplicant and an authentication service.", "explanation": "802.1X: Port-based access control using an authenticated supplicant and an authentication service. The other choices describe different mechanisms or properties.", "options": ["DHCP snooping", "ACL", "Microsegmentation", "802.1X"], "answer": 3, "tier": 1}, {"id": "cert3-4.3-match-4-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "ACL: A configured set of permit and deny rules for traffic or access.\n802.1X: Port-based access control using an authenticated supplicant and an authentication service.\nDHCP snooping: A switch feature that distinguishes trusted DHCP paths and helps reject unauthorized server responses.\nMicrosegmentation: Fine-grained controls limiting communication between workloads or small groups.", "left": ["ACL", "802.1X", "DHCP snooping", "Microsegmentation"], "options": ["A switch feature that distinguishes trusted DHCP paths and helps reject unauthorized server responses.", "A configured set of permit and deny rules for traffic or access.", "Fine-grained controls limiting communication between workloads or small groups.", "Port-based access control using an authenticated supplicant and an authentication service."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-5.1", "title": "Troubleshoot with a hypothesis", "core": 3, "objective": "5.1", "domain": 5, "type": "network", "requires": [], "lore": "Identify the problem, establish and test a theory, plan and implement an authorized fix, verify function, and document. Change one relevant variable at a time when feasible.\n\nYOUR TOOLKIT\n\nProblem identification — Gathering symptoms, scope, timing, recent changes, and user impact.\n\nTheory testing — Using a targeted observation or test to distinguish possible causes.\n\nVerification — Confirming the fix restored required functionality and did not create unacceptable side effects.\n\nTroubleshooting documentation — Recording symptoms, evidence, cause, action, and outcome for future support.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A user says the internet is down. Determine which users and services are affected and when it began before rebooting shared infrastructure.", "questions": [{"id": "cert3-5.1-practice-5-1-0", "prompt": "Which concept best fits this description? Gathering symptoms, scope, timing, recent changes, and user impact.", "explanation": "Problem identification: Gathering symptoms, scope, timing, recent changes, and user impact. The other choices describe different mechanisms or properties.", "options": ["Theory testing", "Troubleshooting documentation", "Verification", "Problem identification"], "answer": 3, "tier": 1}, {"id": "cert3-5.1-practice-5-1-1", "prompt": "Which concept best fits this description? Using a targeted observation or test to distinguish possible causes.", "explanation": "Theory testing: Using a targeted observation or test to distinguish possible causes. The other choices describe different mechanisms or properties.", "options": ["Problem identification", "Troubleshooting documentation", "Theory testing", "Verification"], "answer": 2, "tier": 1}, {"id": "cert3-5.1-match-5-1", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Problem identification: Gathering symptoms, scope, timing, recent changes, and user impact.\nTheory testing: Using a targeted observation or test to distinguish possible causes.\nVerification: Confirming the fix restored required functionality and did not create unacceptable side effects.\nTroubleshooting documentation: Recording symptoms, evidence, cause, action, and outcome for future support.", "left": ["Problem identification", "Theory testing", "Verification", "Troubleshooting documentation"], "options": ["Confirming the fix restored required functionality and did not create unacceptable side effects.", "Gathering symptoms, scope, timing, recent changes, and user impact.", "Recording symptoms, evidence, cause, action, and outcome for future support.", "Using a targeted observation or test to distinguish possible causes."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-5.2", "title": "Find physical faults", "core": 3, "objective": "5.2", "domain": 5, "type": "network", "requires": ["cert3-5.1"], "lore": "Start with link, connectors, patching, distance, media, optics, and power. An address change cannot repair a damaged pair.\n\nYOUR TOOLKIT\n\nWire-map fault — A wiring error such as an open, short, crossed pair, or split pair.\n\nAttenuation — Signal loss over distance or through a medium.\n\nOptical mismatch — Incompatible wavelength, fiber type, or optics at the ends of a fiber link.\n\nPoE fault — Insufficient, incompatible, or failed power delivery to a powered network device.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A copper link negotiates at 100 Mb/s rather than the expected 1 Gb/s. Inspect pair integrity and patch leads before forcing duplex settings.", "questions": [{"id": "cert3-5.2-practice-5-2-0", "prompt": "Which concept best fits this description? A wiring error such as an open, short, crossed pair, or split pair.", "explanation": "Wire-map fault: A wiring error such as an open, short, crossed pair, or split pair. The other choices describe different mechanisms or properties.", "options": ["Attenuation", "PoE fault", "Optical mismatch", "Wire-map fault"], "answer": 3, "tier": 1}, {"id": "cert3-5.2-practice-5-2-1", "prompt": "Which concept best fits this description? Signal loss over distance or through a medium.", "explanation": "Attenuation: Signal loss over distance or through a medium. The other choices describe different mechanisms or properties.", "options": ["Wire-map fault", "PoE fault", "Attenuation", "Optical mismatch"], "answer": 2, "tier": 1}, {"id": "cert3-5.2-match-5-2", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Wire-map fault: A wiring error such as an open, short, crossed pair, or split pair.\nAttenuation: Signal loss over distance or through a medium.\nOptical mismatch: Incompatible wavelength, fiber type, or optics at the ends of a fiber link.\nPoE fault: Insufficient, incompatible, or failed power delivery to a powered network device.", "left": ["Wire-map fault", "Attenuation", "Optical mismatch", "PoE fault"], "options": ["Incompatible wavelength, fiber type, or optics at the ends of a fiber link.", "A wiring error such as an open, short, crossed pair, or split pair.", "Insufficient, incompatible, or failed power delivery to a powered network device.", "Signal loss over distance or through a medium."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-5.3", "title": "Separate configuration and service faults", "core": 3, "objective": "5.3", "domain": 5, "type": "network", "requires": ["cert3-5.2"], "lore": "Check the host configuration and the path in order. VLAN, subnet mask, gateway, DHCP, DNS, and routes each create characteristic symptoms.\n\nYOUR TOOLKIT\n\nIncorrect gateway — A next-hop setting that prevents a host from reaching destinations outside its local network.\n\nDuplicate IP — Two systems using the same address and causing intermittent or conflicting delivery.\n\nDHCP exhaustion — A lease pool with no suitable addresses available for additional clients.\n\nDNS misconfiguration — Incorrect resolver settings or records causing name-resolution failure.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "A host reaches local peers but no remote subnet. Verify its mask, default gateway, and routing path.", "questions": [{"id": "cert3-5.3-practice-5-3-0", "prompt": "Which concept best fits this description? A next-hop setting that prevents a host from reaching destinations outside its local network.", "explanation": "Incorrect gateway: A next-hop setting that prevents a host from reaching destinations outside its local network. The other choices describe different mechanisms or properties.", "options": ["Duplicate IP", "DNS misconfiguration", "DHCP exhaustion", "Incorrect gateway"], "answer": 3, "tier": 1}, {"id": "cert3-5.3-practice-5-3-1", "prompt": "Which concept best fits this description? Two systems using the same address and causing intermittent or conflicting delivery.", "explanation": "Duplicate IP: Two systems using the same address and causing intermittent or conflicting delivery. The other choices describe different mechanisms or properties.", "options": ["Incorrect gateway", "DNS misconfiguration", "Duplicate IP", "DHCP exhaustion"], "answer": 2, "tier": 1}, {"id": "cert3-5.3-match-5-3", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Incorrect gateway: A next-hop setting that prevents a host from reaching destinations outside its local network.\nDuplicate IP: Two systems using the same address and causing intermittent or conflicting delivery.\nDHCP exhaustion: A lease pool with no suitable addresses available for additional clients.\nDNS misconfiguration: Incorrect resolver settings or records causing name-resolution failure.", "left": ["Incorrect gateway", "Duplicate IP", "DHCP exhaustion", "DNS misconfiguration"], "options": ["A lease pool with no suitable addresses available for additional clients.", "A next-hop setting that prevents a host from reaching destinations outside its local network.", "Incorrect resolver settings or records causing name-resolution failure.", "Two systems using the same address and causing intermittent or conflicting delivery."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-5.4", "title": "Diagnose performance without guessing", "core": 3, "objective": "5.4", "domain": 5, "type": "network", "requires": ["cert3-5.3"], "lore": "Measure delay, variation, loss, throughput, and resource usage. A fast nominal link can still perform poorly because of congestion, errors, or an overloaded endpoint.\n\nYOUR TOOLKIT\n\nLatency — Time taken for traffic to travel through a measured path.\n\nJitter — Variation in packet delay, especially relevant to real-time applications.\n\nPacket loss — Traffic failing to reach its destination, which can degrade real-time service and trigger retransmission.\n\nCongestion — Demand exceeding available forwarding or transmission capacity.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Voice calls break up when a backup saturates the WAN. Measure loss and jitter, then assess capacity and traffic policy.", "questions": [{"id": "cert3-5.4-practice-5-4-0", "prompt": "Which concept best fits this description? Time taken for traffic to travel through a measured path.", "explanation": "Latency: Time taken for traffic to travel through a measured path. The other choices describe different mechanisms or properties.", "options": ["Jitter", "Congestion", "Packet loss", "Latency"], "answer": 3, "tier": 1}, {"id": "cert3-5.4-practice-5-4-1", "prompt": "Which concept best fits this description? Variation in packet delay, especially relevant to real-time applications.", "explanation": "Jitter: Variation in packet delay, especially relevant to real-time applications. The other choices describe different mechanisms or properties.", "options": ["Latency", "Congestion", "Jitter", "Packet loss"], "answer": 2, "tier": 1}, {"id": "cert3-5.4-match-5-4", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Latency: Time taken for traffic to travel through a measured path.\nJitter: Variation in packet delay, especially relevant to real-time applications.\nPacket loss: Traffic failing to reach its destination, which can degrade real-time service and trigger retransmission.\nCongestion: Demand exceeding available forwarding or transmission capacity.", "left": ["Latency", "Jitter", "Packet loss", "Congestion"], "options": ["Traffic failing to reach its destination, which can degrade real-time service and trigger retransmission.", "Time taken for traffic to travel through a measured path.", "Demand exceeding available forwarding or transmission capacity.", "Variation in packet delay, especially relevant to real-time applications."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert3-5.4-scenario-5-4-0", "prompt": "Voice breaks up while a large backup fills the WAN link. Router interfaces show no physical errors.\n\nWhich measurements are most relevant?", "explanation": "Real-time traffic is sensitive to delay variation and loss under congestion.", "options": ["Monitor brightness", "Loss, latency, jitter, and utilization", "Keyboard repeat rate"], "answer": 1, "tier": 3}, {"id": "cert3-5.4-scenario-5-4-1", "prompt": "Voice breaks up while a large backup fills the WAN link. Router interfaces show no physical errors.\n\nWhich response best fits the evidence?", "explanation": "Capacity and traffic policy address the stated competing-load problem.", "options": ["Replace every DNS record", "Disable all voice encryption", "Assess capacity and apply a tested traffic-management policy"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert3-5.5", "title": "Choose a diagnostic tool", "core": 3, "objective": "5.5", "domain": 5, "type": "network", "requires": ["cert3-5.4"], "lore": "Use a tool that answers a specific question, and interpret its limits. A failed ping can reflect filtering rather than complete service failure.\n\nYOUR TOOLKIT\n\nPing — An ICMP reachability test whose success or failure must be interpreted with filtering and routing context.\n\nTraceroute — A path-probing method that reveals responding hops but may be affected by filtering or asymmetric routing.\n\nPacket analyzer — A tool for examining captured network protocol details.\n\nCable tester — An instrument checking physical cabling properties such as continuity or wire mapping.\n\nMISSION HABIT\n\nName the requirement, identify the relevant layer or component, test one useful theory, and verify the result. When the evidence is insufficient, gather more information rather than making an irreversible guess.", "example": "Name lookup works but HTTPS fails. Test the destination port and application handshake instead of declaring DNS broken.", "questions": [{"id": "cert3-5.5-practice-5-5-0", "prompt": "Which concept best fits this description? An ICMP reachability test whose success or failure must be interpreted with filtering and routing context.", "explanation": "Ping: An ICMP reachability test whose success or failure must be interpreted with filtering and routing context. The other choices describe different mechanisms or properties.", "options": ["Traceroute", "Cable tester", "Packet analyzer", "Ping"], "answer": 3, "tier": 1}, {"id": "cert3-5.5-practice-5-5-1", "prompt": "Which concept best fits this description? A path-probing method that reveals responding hops but may be affected by filtering or asymmetric routing.", "explanation": "Traceroute: A path-probing method that reveals responding hops but may be affected by filtering or asymmetric routing. The other choices describe different mechanisms or properties.", "options": ["Ping", "Cable tester", "Traceroute", "Packet analyzer"], "answer": 2, "tier": 1}, {"id": "cert3-5.5-match-5-5", "prompt": "Equip your toolkit: match each concept to its purpose.", "explanation": "Ping: An ICMP reachability test whose success or failure must be interpreted with filtering and routing context.\nTraceroute: A path-probing method that reveals responding hops but may be affected by filtering or asymmetric routing.\nPacket analyzer: A tool for examining captured network protocol details.\nCable tester: An instrument checking physical cabling properties such as continuity or wire mapping.", "left": ["Ping", "Traceroute", "Packet analyzer", "Cable tester"], "options": ["A tool for examining captured network protocol details.", "An ICMP reachability test whose success or failure must be interpreted with filtering and routing context.", "An instrument checking physical cabling properties such as continuity or wire mapping.", "A path-probing method that reveals responding hops but may be affected by filtering or asymmetric routing."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA N10-009 official objectives · document 6.0", "url": "https://lecbyo.files.cmp.optimizely.com/download/35a7403ab73211ef9dcda6f347fbf652", "accessed": "2026-11-03"}, {"id": "technical", "title": "IETF RFC 8200 · IPv6 reference", "url": "https://www.rfc-editor.org/rfc/rfc8200", "accessed": "2026-11-03"}]}, {"id": "cert4-1.1", "title": "Choose controls that fit the job", "core": 4, "objective": "1.1", "domain": 1, "type": "security", "requires": [], "lore": "A control is a safeguard chosen to change risk. Classify it along two independent axes: how it is implemented and what it does. A firewall can be technical and preventive at the same time. The same technology may serve several functions depending on how it is used. Start with the business risk, then choose a control that acts at the right point. A camera recording evidence is primarily detective; a visible camera may also deter.\n\nFIELD NOTES\n\nTechnical control — A safeguard enforced by technology, such as a firewall rule blocking an unauthorized connection.\n\nManagerial control — A management decision or documented risk policy that sets security expectations and accountability.\n\nOperational control — A safeguard performed through people and repeatable procedures, such as an operator reviewing access logs.\n\nPhysical control — A tangible barrier or environmental safeguard, such as a fence, lock, or bollard.\n\nPreventive control — A safeguard intended to stop an unwanted action before it succeeds, such as rejecting an unauthorized login.\n\nDetective control — A safeguard that identifies activity or a condition, such as an alert when an account is used unusually.\n\nCorrective control — A safeguard used to repair harm or restore a secure condition after a problem, such as reimaging an infected system.\n\nCompensating control — An alternative safeguard used to address a requirement when the preferred control cannot reasonably be implemented.\n\nDeterrent control — A safeguard intended to discourage an attempt, such as a warning sign announcing monitoring.\n\nDirective control — A safeguard that instructs expected behavior, such as a policy requiring employees to report suspicious messages.\n\nPUT IT IN CONTEXT\n\nKeep category and function separate. A physical fence can be preventive, a management policy directive, and a person reviewing alerts operational and detective. A compensating safeguard must address the same risk adequately; it is not permission to skip a requirement.", "example": "A warehouse loses equipment after hours. Locked doors prevent casual entry, a guard follows a patrol procedure, cameras record events, and an inventory policy assigns accountability. Label each safeguard by implementation category and intended function rather than calling everything preventive.", "questions": [{"id": "cert4-1.1-practice-1-1-0", "prompt": "Which concept best fits this description? A safeguard enforced by technology, such as a firewall rule blocking an unauthorized connection.", "explanation": "Technical control: A safeguard enforced by technology, such as a firewall rule blocking an unauthorized connection. The other choices describe different mechanisms or properties.", "options": ["Managerial control", "Physical control", "Corrective control", "Technical control"], "answer": 3, "tier": 1}, {"id": "cert4-1.1-practice-1-1-1", "prompt": "Which concept best fits this description? A management decision or documented risk policy that sets security expectations and accountability.", "explanation": "Managerial control: A management decision or documented risk policy that sets security expectations and accountability. The other choices describe different mechanisms or properties.", "options": ["Preventive control", "Compensating control", "Managerial control", "Operational control"], "answer": 2, "tier": 1}, {"id": "cert4-1.1-match-1-1", "prompt": "Match the field notes to their meaning.", "explanation": "Operational control: A safeguard performed through people and repeatable procedures, such as an operator reviewing access logs.\nPreventive control: A safeguard intended to stop an unwanted action before it succeeds, such as rejecting an unauthorized login.\nCorrective control: A safeguard used to repair harm or restore a secure condition after a problem, such as reimaging an infected system.\nDeterrent control: A safeguard intended to discourage an attempt, such as a warning sign announcing monitoring.", "left": ["Operational control", "Preventive control", "Corrective control", "Deterrent control"], "options": ["A safeguard used to repair harm or restore a secure condition after a problem, such as reimaging an infected system.", "A safeguard performed through people and repeatable procedures, such as an operator reviewing access logs.", "A safeguard intended to discourage an attempt, such as a warning sign announcing monitoring.", "A safeguard intended to stop an unwanted action before it succeeds, such as rejecting an unauthorized login."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-1.1-scenario-1-1-0", "prompt": "The warehouse needs fewer thefts and useful evidence. A camera has not stopped theft by itself.\n\nWhich addition primarily prevents casual unauthorized entry?", "explanation": "The locked door restricts entry before it succeeds; a record alone does not.", "options": ["A locked, access-controlled door", "An incident summary", "An annual inventory chart"], "answer": 0, "tier": 3}, {"id": "cert4-1.1-scenario-1-1-1", "prompt": "The warehouse needs fewer thefts and useful evidence. A camera has not stopped theft by itself.\n\nWhich safeguard provides detective evidence?", "explanation": "Recorded footage can help establish that an event occurred.", "options": ["A password policy", "A camera recording reviewed after an alert", "A spare door key"], "answer": 1, "tier": 3}, {"id": "cert4-1.1-scenario-1-1-2", "prompt": "The warehouse needs fewer thefts and useful evidence. A camera has not stopped theft by itself.\n\nWhich category fits a documented patrol performed by a guard?", "explanation": "The repeatable human activity is operational; the physical location does not change that implementation category.", "options": ["Cryptographic", "Technical only", "Operational"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-1.2", "title": "Think in security properties", "core": 4, "objective": "1.2", "domain": 1, "type": "security", "requires": ["cert4-1.1"], "lore": "Security properties describe what you are protecting, not which product to buy. Confidentiality concerns disclosure, integrity concerns unauthorized alteration, and availability concerns timely access. Authentication, authorization, and accounting are separate decisions. Zero trust means a network location alone does not establish trust. A policy decision should consider identity, device condition, and resource sensitivity before an enforcement point permits access.\n\nFIELD NOTES\n\nConfidentiality — Preventing unauthorized disclosure, such as ensuring only payroll staff can read salary records.\n\nIntegrity — Protecting information against unauthorized alteration, such as detecting that a configuration file was changed.\n\nAvailability — Ensuring authorized users can obtain a service when needed, such as keeping a patient portal reachable.\n\nAuthentication — Establishing a claimed identity using evidence such as a password, authenticator, or device certificate.\n\nAuthorization — Deciding which resources an established identity may access and which actions it may perform.\n\nAccounting — Recording attributable activity so reviewers can determine which identity performed an action and when.\n\nNon-repudiation — Evidence supporting attribution of an action or message, commonly through controlled digital signatures and audit records.\n\nZero trust — An approach that does not grant implicit trust merely because a device or user is on an internal network.\n\nPolicy enforcement point — The component that permits or blocks a resource connection according to the access decision made in the control plane.\n\nHoneytoken — A deliberately planted decoy credential or record whose unexpected use can reveal unauthorized activity.\n\nPUT IT IN CONTEXT\n\nA gap analysis compares a current state with a required target. In zero trust, the policy engine decides, the policy administrator establishes the authorized path, and the enforcement point applies the decision to data-plane traffic. Physical safeguards include fences and bollards, access vestibules, badges, guards, lighting, cameras, and infrared, pressure, microwave, or ultrasonic sensors. A honeypot is a decoy host, a honeynet a decoy network, and a honeyfile a decoy document.", "example": "A contractor passes MFA but attempts to open payroll. Their identity has been authenticated; payroll access is still an authorization decision. Recording the denied request supplies accounting evidence. A valid login does not imply unrestricted access.", "questions": [{"id": "cert4-1.2-practice-1-2-0", "prompt": "Which concept best fits this description? Preventing unauthorized disclosure, such as ensuring only payroll staff can read salary records.", "explanation": "Confidentiality: Preventing unauthorized disclosure, such as ensuring only payroll staff can read salary records. The other choices describe different mechanisms or properties.", "options": ["Integrity", "Authentication", "Non-repudiation", "Confidentiality"], "answer": 3, "tier": 1}, {"id": "cert4-1.2-practice-1-2-1", "prompt": "Which concept best fits this description? Protecting information against unauthorized alteration, such as detecting that a configuration file was changed.", "explanation": "Integrity: Protecting information against unauthorized alteration, such as detecting that a configuration file was changed. The other choices describe different mechanisms or properties.", "options": ["Authorization", "Zero trust", "Integrity", "Availability"], "answer": 2, "tier": 1}, {"id": "cert4-1.2-match-1-2", "prompt": "Match the field notes to their meaning.", "explanation": "Availability: Ensuring authorized users can obtain a service when needed, such as keeping a patient portal reachable.\nAuthorization: Deciding which resources an established identity may access and which actions it may perform.\nNon-repudiation: Evidence supporting attribution of an action or message, commonly through controlled digital signatures and audit records.\nPolicy enforcement point: The component that permits or blocks a resource connection according to the access decision made in the control plane.", "left": ["Availability", "Authorization", "Non-repudiation", "Policy enforcement point"], "options": ["Evidence supporting attribution of an action or message, commonly through controlled digital signatures and audit records.", "Ensuring authorized users can obtain a service when needed, such as keeping a patient portal reachable.", "The component that permits or blocks a resource connection according to the access decision made in the control plane.", "Deciding which resources an established identity may access and which actions it may perform."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-1.3", "title": "Change systems without losing control", "core": 4, "objective": "1.3", "domain": 1, "type": "security", "requires": ["cert4-1.2"], "lore": "A security improvement can create an outage if dependencies are ignored. Change management turns an intention into an approved, testable, recoverable action. Identify an owner and affected stakeholders, assess impact, test realistic conditions, and decide what evidence will establish success. A maintenance window controls timing; it does not prove the change is safe. Keep the backout plan usable even when the changed system cannot be reached.\n\nFIELD NOTES\n\nImpact analysis — Evaluating how a proposed change could affect security, service availability, users, and dependent systems.\n\nChange approval — An accountable authorization to carry out a defined change after its risk and expected benefit have been assessed.\n\nBackout plan — A documented way to return to a known acceptable state when a change fails its verification criteria.\n\nMaintenance window — An agreed time period for performing work that may disrupt normal service.\n\nDependency mapping — Identifying upstream and downstream services that must continue working when a component changes.\n\nVersion control — Maintaining traceable revisions so reviewers can compare changes and recover an earlier configuration.\n\nStandard operating procedure — A repeatable set of instructions describing how an authorized operational task should be performed.\n\nStakeholder communication — Informing affected owners and users about expected impact, timing, responsibilities, and recovery decisions.\n\nTest evidence — Recorded results showing whether a proposed change met defined requirements before or after deployment.\n\nDocumentation update — Revising diagrams, inventories, policies, or procedures so they describe the deployed state rather than an obsolete design.\n\nPUT IT IN CONTEXT\n\nAllow/deny lists and restricted activities may change during deployment. Identify whether the work needs a service restart, application restart, or full downtime, especially for legacy dependencies. Record ownership, approvals, stakeholder notifications, tested recovery steps, and any procedure changes in a traceable revision.", "example": "A firewall update might block the database port used by checkout. Test the dependency, preserve the old configuration, arrange console access, approve a maintenance window, and define a rollback trigger such as failed checkout tests. Update the diagram and version history after verification.", "questions": [{"id": "cert4-1.3-practice-1-3-0", "prompt": "Which concept best fits this description? Evaluating how a proposed change could affect security, service availability, users, and dependent systems.", "explanation": "Impact analysis: Evaluating how a proposed change could affect security, service availability, users, and dependent systems. The other choices describe different mechanisms or properties.", "options": ["Change approval", "Maintenance window", "Standard operating procedure", "Impact analysis"], "answer": 3, "tier": 1}, {"id": "cert4-1.3-practice-1-3-1", "prompt": "Which concept best fits this description? An accountable authorization to carry out a defined change after its risk and expected benefit have been assessed.", "explanation": "Change approval: An accountable authorization to carry out a defined change after its risk and expected benefit have been assessed. The other choices describe different mechanisms or properties.", "options": ["Dependency mapping", "Stakeholder communication", "Change approval", "Backout plan"], "answer": 2, "tier": 1}, {"id": "cert4-1.3-match-1-3", "prompt": "Match the field notes to their meaning.", "explanation": "Backout plan: A documented way to return to a known acceptable state when a change fails its verification criteria.\nDependency mapping: Identifying upstream and downstream services that must continue working when a component changes.\nStandard operating procedure: A repeatable set of instructions describing how an authorized operational task should be performed.\nTest evidence: Recorded results showing whether a proposed change met defined requirements before or after deployment.", "left": ["Backout plan", "Dependency mapping", "Standard operating procedure", "Test evidence"], "options": ["A repeatable set of instructions describing how an authorized operational task should be performed.", "A documented way to return to a known acceptable state when a change fails its verification criteria.", "Recorded results showing whether a proposed change met defined requirements before or after deployment.", "Identifying upstream and downstream services that must continue working when a component changes."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-1.3-change-order", "prompt": "Sequence this simplified approved-change workflow.", "explanation": "First assess/test, then approve and prepare recovery, deploy in the agreed window, and finally verify/document. Emergency processes can differ but still need accountability.", "left": ["Step 1", "Step 2", "Step 3", "Step 4"], "options": ["Deploy within the approved window", "Assess impact and test the proposed change", "Verify service and update records", "Obtain required approval and confirm rollback readiness"], "answer": [1, 3, 0, 2], "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-1.4", "title": "Use cryptography for the right purpose", "core": 4, "objective": "1.4", "domain": 1, "type": "security", "requires": ["cert4-1.3"], "lore": "Encryption protects confidentiality; it is not the same as hashing or signing. A hash is a fixed-length digest used for comparison, while a digital signature supports integrity and origin verification. Symmetric cryptography is efficient for bulk data. Asymmetric techniques support key agreement and signatures using distinct public and private keys. Protect key material throughout generation, storage, use, rotation, recovery, and destruction. A strong algorithm cannot compensate for exposed keys.\n\nFIELD NOTES\n\nSymmetric encryption — Using shared secret key material for efficient bulk encryption and decryption; both endpoints must protect that secret.\n\nAsymmetric cryptography — Using a related public and private key pair for operations such as signatures or establishing a shared secret.\n\nCryptographic hash — Producing a fixed-length digest for integrity comparison; it is not reversible encryption and does not itself authenticate the source.\n\nPassword salting — Adding a unique nonsecret value to each password before a password-hashing operation to defeat shared precomputed results.\n\nKey stretching — Increasing the cost of password guessing with a deliberately expensive password derivation function.\n\nDigital signature — Using a private signing key to produce evidence that a public key can verify for message integrity and signer attribution.\n\nCertificate authority — An entity that signs certificates binding public keys to identities within a public key infrastructure.\n\nCertificate revocation check — Using a CRL or OCSP mechanism to learn whether an issued certificate has been revoked before its expiry.\n\nHardware security module — Dedicated hardware designed to protect cryptographic keys and perform controlled cryptographic operations.\n\nTokenization — Replacing a sensitive value with a substitute token while keeping the sensitive mapping in a separately protected system.\n\nPUT IT IN CONTEXT\n\nApply encryption at the needed level: full disk, partition, volume, file, database, record, or communication channel. Full-disk protection does not restrict an already authorized application. Key length and algorithm must suit the use case. A TPM protects device-related key material; a secure enclave isolates sensitive processing; a key management system controls lifecycle; escrow retains an authorized recovery copy. Steganography hides the existence of information, masking conceals values, and tokenization substitutes them. A CSR requests a certificate; a CA chain leads to a trusted root. Self-signed certificates require an independently established trust path. Wildcard certificates cover specified subdomains but widen key-compromise impact. A blockchain is a linked ledger protected by consensus and cryptographic structures, not automatic confidentiality.", "example": "A download is signed by the publisher. Verify its signature using a trusted public key to check origin and integrity. An unsigned hash published next to a file only helps if the expected hash arrives through a trusted path. TLS additionally protects a live transport session; it does not prove the downloaded application is harmless.", "questions": [{"id": "cert4-1.4-practice-1-4-0", "prompt": "Which concept best fits this description? Using shared secret key material for efficient bulk encryption and decryption; both endpoints must protect that secret.", "explanation": "Symmetric encryption: Using shared secret key material for efficient bulk encryption and decryption; both endpoints must protect that secret. The other choices describe different mechanisms or properties.", "options": ["Asymmetric cryptography", "Password salting", "Certificate authority", "Symmetric encryption"], "answer": 3, "tier": 1}, {"id": "cert4-1.4-practice-1-4-1", "prompt": "Which concept best fits this description? Using a related public and private key pair for operations such as signatures or establishing a shared secret.", "explanation": "Asymmetric cryptography: Using a related public and private key pair for operations such as signatures or establishing a shared secret. The other choices describe different mechanisms or properties.", "options": ["Key stretching", "Certificate revocation check", "Asymmetric cryptography", "Cryptographic hash"], "answer": 2, "tier": 1}, {"id": "cert4-1.4-match-1-4", "prompt": "Match the field notes to their meaning.", "explanation": "Cryptographic hash: Producing a fixed-length digest for integrity comparison; it is not reversible encryption and does not itself authenticate the source.\nKey stretching: Increasing the cost of password guessing with a deliberately expensive password derivation function.\nCertificate authority: An entity that signs certificates binding public keys to identities within a public key infrastructure.\nHardware security module: Dedicated hardware designed to protect cryptographic keys and perform controlled cryptographic operations.", "left": ["Cryptographic hash", "Key stretching", "Certificate authority", "Hardware security module"], "options": ["An entity that signs certificates binding public keys to identities within a public key infrastructure.", "Producing a fixed-length digest for integrity comparison; it is not reversible encryption and does not itself authenticate the source.", "Dedicated hardware designed to protect cryptographic keys and perform controlled cryptographic operations.", "Increasing the cost of password guessing with a deliberately expensive password derivation function."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-1.4-scenario-1-4-0", "prompt": "You have a downloaded installer, a detached signature, and the publisher's public key obtained through a trusted channel.\n\nWhich check supports publisher attribution and integrity?", "explanation": "A valid signature under a trusted publisher key supports origin and integrity.", "options": ["Decrypt the file with your own private key", "Verify the signature with the trusted publisher public key", "Compare file names"], "answer": 1, "tier": 3}, {"id": "cert4-1.4-scenario-1-4-1", "prompt": "You have a downloaded installer, a detached signature, and the publisher's public key obtained through a trusted channel.\n\nWhat does that verification NOT establish?", "explanation": "Signed software can still contain vulnerabilities or malicious functionality.", "options": ["The signing key matches", "The signed bytes are intact", "The program is free of every vulnerability"], "answer": 2, "tier": 3}, {"id": "cert4-1.4-scenario-1-4-2", "prompt": "You have a downloaded installer, a detached signature, and the publisher's public key obtained through a trusted channel.\n\nWhere should a publisher protect its high-value signing key?", "explanation": "Controlled signing and protected key material reduce unauthorized signing risk.", "options": ["A controlled signing service backed by protected key storage", "A public code repository", "An email attachment shared by all developers"], "answer": 0, "tier": 3}, {"id": "cert4-1.4-crypto-select", "prompt": "Which TWO properties are supported by verifying a digital signature using a trusted signer public key?", "explanation": "Signature verification supports integrity and attribution under the trusted key. It does not hide plaintext or prove software is vulnerability-free.", "kind": "multi", "options": ["Integrity of the signed message", "Evidence of signer attribution", "Confidentiality of the plaintext message", "Proof that the application has no vulnerabilities"], "answer": [0, 1], "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-2.1", "title": "Reason about actors and motives", "core": 4, "objective": "2.1", "domain": 2, "type": "security", "requires": [], "lore": "An actor is the source of a threat; a motive explains the desired outcome. Capabilities, access, resources, and intent are related but distinct. Do not attribute an intrusion to a country merely because an IP address is geolocated there. Internal access can be malicious, accidental, or compromised. Shadow IT creates ungoverned risk even when its users intend to help. Match controls to plausible behavior and exposure instead of stereotypes.\n\nFIELD NOTES\n\nNation-state actor — A state-linked threat source that may have sustained resources for strategic espionage or disruption.\n\nOrganized crime actor — A coordinated criminal group commonly motivated by financial gain through fraud, extortion, or sale of access.\n\nHacktivist — An actor motivated primarily by an ideological, social, or political cause.\n\nInsider threat — Risk arising from someone with legitimate organizational access, including deliberate misuse or harmful mistakes.\n\nUnskilled attacker — An actor who relies heavily on existing tools or instructions rather than developing sophisticated techniques.\n\nShadow IT — Technology adopted outside the organization's approved governance and visibility, such as an unapproved storage service.\n\nEspionage — A motive centered on obtaining sensitive information for strategic or competitive advantage.\n\nExtortion — Demanding payment or another concession under threat of damage, disclosure, or continued disruption.\n\nData exfiltration — Moving information out of an authorized environment without permission.\n\nActor capability assessment — Evaluating resources, sophistication, persistence, and access separately from the actor's stated or suspected motivation.\n\nPUT IT IN CONTEXT\n\nConsider internal versus external access, funding, and sophistication separately. Motives include financial gain, data theft, espionage, disruption, blackmail, ideology, revenge, chaos, or war. Ethical testing has authorization and boundaries. An observed technique can be shared by many actor groups, so attribution needs stronger evidence than a tool name.", "example": "An employee uploads customer data to a personal file-sharing account to work faster. That is shadow IT and a data exposure concern, even without revenge or profit as a motive. Investigate intent separately from the facts needed to contain the exposure.", "questions": [{"id": "cert4-2.1-practice-2-1-0", "prompt": "Which concept best fits this description? A state-linked threat source that may have sustained resources for strategic espionage or disruption.", "explanation": "Nation-state actor: A state-linked threat source that may have sustained resources for strategic espionage or disruption. The other choices describe different mechanisms or properties.", "options": ["Insider threat", "Espionage", "Nation-state actor", "Organized crime actor"], "answer": 2, "tier": 1}, {"id": "cert4-2.1-practice-2-1-1", "prompt": "Which concept best fits this description? A coordinated criminal group commonly motivated by financial gain through fraud, extortion, or sale of access.", "explanation": "Organized crime actor: A coordinated criminal group commonly motivated by financial gain through fraud, extortion, or sale of access. The other choices describe different mechanisms or properties.", "options": ["Extortion", "Organized crime actor", "Hacktivist", "Unskilled attacker"], "answer": 1, "tier": 1}, {"id": "cert4-2.1-match-2-1", "prompt": "Match the field notes to their meaning.", "explanation": "Hacktivist: An actor motivated primarily by an ideological, social, or political cause.\nUnskilled attacker: An actor who relies heavily on existing tools or instructions rather than developing sophisticated techniques.\nEspionage: A motive centered on obtaining sensitive information for strategic or competitive advantage.\nData exfiltration: Moving information out of an authorized environment without permission.", "left": ["Hacktivist", "Unskilled attacker", "Espionage", "Data exfiltration"], "options": ["A motive centered on obtaining sensitive information for strategic or competitive advantage.", "An actor motivated primarily by an ideological, social, or political cause.", "Moving information out of an authorized environment without permission.", "An actor who relies heavily on existing tools or instructions rather than developing sophisticated techniques."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-2.2", "title": "Find the entry points", "core": 4, "objective": "2.2", "domain": 2, "type": "security", "requires": ["cert4-2.1"], "lore": "An attack vector is a route into a target; the attack surface is the collection of exposed opportunities. People, software, devices, vendors, and communications all create entry points. Reduce unnecessary exposure and verify requests through a separate trusted channel. A recognizable logo is weak evidence of legitimacy. A message can be dangerous without an attachment, especially when it asks for credentials, payment, or a change to trust relationships.\n\nFIELD NOTES\n\nPhishing — Deceptive messages intended to induce a harmful action such as revealing credentials or opening a malicious link.\n\nSmishing — Phishing delivered through SMS or similar text messages.\n\nVishing — Social engineering conducted through a voice call, often impersonating a trusted authority.\n\nBusiness email compromise — Impersonating or compromising a business mailbox to manipulate payments, data sharing, or other business actions.\n\nPretexting — Using a fabricated situation or identity to persuade someone to disclose information or take an action.\n\nWatering-hole attack — Compromising a site frequented by intended targets so visiting that site becomes an infection or credential-theft route.\n\nTyposquatting — Registering a lookalike or commonly mistyped domain to divert users from the intended service.\n\nSupply-chain vector — Reaching a target through a trusted vendor, service provider, hardware component, or software dependency.\n\nDefault credential exposure — Leaving vendor-supplied login secrets unchanged so an attacker can use predictable credentials.\n\nOpen service exposure — Making a listening network service reachable by an unnecessary audience, increasing the system's attack surface.\n\nPUT IT IN CONTEXT\n\nEntry points also include images, files, removable devices, vulnerable clients, agentless interfaces, unsupported software, wireless, wired links, and Bluetooth. Message channels include email, SMS, and instant messaging. Misinformation can be false without deliberate intent; disinformation is intentionally misleading. Brand impersonation borrows a trusted identity. Reduce open ports and unneeded connectivity, and verify providers as well as directly connected systems.", "example": "An urgent text claims that a package fee must be paid at a misspelled delivery-company domain. The channel makes it smishing; the lookalike domain is typosquatting. Do not follow the supplied link to verify it. Open the known official service independently or report through the established process.", "questions": [{"id": "cert4-2.2-practice-2-2-0", "prompt": "Which concept best fits this description? Deceptive messages intended to induce a harmful action such as revealing credentials or opening a malicious link.", "explanation": "Phishing: Deceptive messages intended to induce a harmful action such as revealing credentials or opening a malicious link. The other choices describe different mechanisms or properties.", "options": ["Business email compromise", "Typosquatting", "Phishing", "Smishing"], "answer": 2, "tier": 1}, {"id": "cert4-2.2-practice-2-2-1", "prompt": "Which concept best fits this description? Phishing delivered through SMS or similar text messages.", "explanation": "Smishing: Phishing delivered through SMS or similar text messages. The other choices describe different mechanisms or properties.", "options": ["Supply-chain vector", "Smishing", "Vishing", "Pretexting"], "answer": 1, "tier": 1}, {"id": "cert4-2.2-match-2-2", "prompt": "Match the field notes to their meaning.", "explanation": "Vishing: Social engineering conducted through a voice call, often impersonating a trusted authority.\nPretexting: Using a fabricated situation or identity to persuade someone to disclose information or take an action.\nTyposquatting: Registering a lookalike or commonly mistyped domain to divert users from the intended service.\nDefault credential exposure: Leaving vendor-supplied login secrets unchanged so an attacker can use predictable credentials.", "left": ["Vishing", "Pretexting", "Typosquatting", "Default credential exposure"], "options": ["Registering a lookalike or commonly mistyped domain to divert users from the intended service.", "Social engineering conducted through a voice call, often impersonating a trusted authority.", "Leaving vendor-supplied login secrets unchanged so an attacker can use predictable credentials.", "Using a fabricated situation or identity to persuade someone to disclose information or take an action."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-2.2-scenario-2-2-0", "prompt": "From: Finance Director <finance@payr0ll.example>\nSubject: CONFIDENTIAL — urgent bank change\nPlease change the vendor's banking details today. Do not call me; I am in a meeting.\nYour organization normally uses payroll.example.\n\nWhich detail is a concrete warning sign?", "explanation": "The altered domain and pressure to skip checks provide specific warning signs.", "options": ["A request to bypass normal verification plus a lookalike domain", "The use of ordinary text", "The fact that a director can send email"], "answer": 0, "tier": 3}, {"id": "cert4-2.2-scenario-2-2-1", "prompt": "From: Finance Director <finance@payr0ll.example>\nSubject: CONFIDENTIAL — urgent bank change\nPlease change the vendor's banking details today. Do not call me; I am in a meeting.\nYour organization normally uses payroll.example.\n\nHow should you verify the request?", "explanation": "A separately established channel avoids trusting attacker-supplied contact information.", "options": ["Reply to the supplied sender", "Call a previously established trusted contact number", "Use the phone number in the suspicious signature"], "answer": 1, "tier": 3}, {"id": "cert4-2.2-scenario-2-2-2", "prompt": "From: Finance Director <finance@payr0ll.example>\nSubject: CONFIDENTIAL — urgent bank change\nPlease change the vendor's banking details today. Do not call me; I am in a meeting.\nYour organization normally uses payroll.example.\n\nWhat is the useful next reporting action?", "explanation": "Approved reporting lets the organization investigate and protect other recipients.", "options": ["Forward it to every coworker as an attachment", "Delete all related logs", "Report using the approved phishing or finance-fraud process"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-2.3", "title": "Recognize the weakness before the exploit", "core": 4, "objective": "2.3", "domain": 2, "type": "security", "requires": ["cert4-2.2"], "lore": "A vulnerability is a weakness that could be exploited. An exploit is a method that takes advantage of it. Weaknesses can exist in code, configuration, dependencies, firmware, or lifecycle decisions. Distinguish code injection from browser script execution and distinguish a guest compromise from crossing a virtualization boundary. Unsupported systems remain a risk even when no new patch is available. Use a supported replacement or compensating isolation, not wishful monitoring.\n\nFIELD NOTES\n\nSQL injection — Untrusted input changes the structure of a database query because code and data were not properly separated.\n\nCross-site scripting — Untrusted content is executed as script in a victim's browser within the context of a vulnerable site.\n\nBuffer overflow — Writing more data than a memory buffer can hold, potentially corrupting adjacent memory or control flow.\n\nRace condition — A flaw caused by operations occurring in an unexpected timing or sequence, including a change between checking and using a resource.\n\nVM escape — Crossing the intended isolation boundary from a virtual machine into its host environment.\n\nResource reuse exposure — Sensitive information remains available when memory or storage is reassigned without appropriate clearing or isolation.\n\nZero-day vulnerability — A vulnerability for which defenders do not yet have an available corrective fix at the time it is exploited or disclosed.\n\nEnd-of-life system risk — Continued use of a platform whose vendor no longer supplies normal security maintenance.\n\nMisconfiguration — An insecure setting or deployment decision, such as a publicly readable storage bucket containing private records.\n\nSideloading risk — Installing mobile software outside the managed or approved distribution path, bypassing expected vetting and controls.\n\nPUT IT IN CONTEXT\n\nMemory injection places code or data into another process; a malicious update abuses a trusted maintenance path. Firmware defects and unsupported legacy hardware may require lifecycle treatment. In cloud deployments, check tenant permissions and exposed storage. Cryptographic weaknesses include obsolete algorithms and poor key handling. Jailbreaking removes mobile platform restrictions and can undermine management assumptions. Time-of-check/time-of-use flaws arise when a checked resource changes before the action uses it.", "example": "A search page inserts user text directly into a database command. Parameterized queries separate data from SQL syntax and address this injection path. HTML output encoding solves a different problem: preventing untrusted text from becoming browser-executed markup or script.", "questions": [{"id": "cert4-2.3-practice-2-3-0", "prompt": "Which concept best fits this description? Untrusted input changes the structure of a database query because code and data were not properly separated.", "explanation": "SQL injection: Untrusted input changes the structure of a database query because code and data were not properly separated. The other choices describe different mechanisms or properties.", "options": ["Race condition", "Zero-day vulnerability", "SQL injection", "Cross-site scripting"], "answer": 2, "tier": 1}, {"id": "cert4-2.3-practice-2-3-1", "prompt": "Which concept best fits this description? Untrusted content is executed as script in a victim's browser within the context of a vulnerable site.", "explanation": "Cross-site scripting: Untrusted content is executed as script in a victim's browser within the context of a vulnerable site. The other choices describe different mechanisms or properties.", "options": ["End-of-life system risk", "Cross-site scripting", "Buffer overflow", "VM escape"], "answer": 1, "tier": 1}, {"id": "cert4-2.3-match-2-3", "prompt": "Match the field notes to their meaning.", "explanation": "Buffer overflow: Writing more data than a memory buffer can hold, potentially corrupting adjacent memory or control flow.\nVM escape: Crossing the intended isolation boundary from a virtual machine into its host environment.\nZero-day vulnerability: A vulnerability for which defenders do not yet have an available corrective fix at the time it is exploited or disclosed.\nMisconfiguration: An insecure setting or deployment decision, such as a publicly readable storage bucket containing private records.", "left": ["Buffer overflow", "VM escape", "Zero-day vulnerability", "Misconfiguration"], "options": ["A vulnerability for which defenders do not yet have an available corrective fix at the time it is exploited or disclosed.", "Writing more data than a memory buffer can hold, potentially corrupting adjacent memory or control flow.", "An insecure setting or deployment decision, such as a publicly readable storage bucket containing private records.", "Crossing the intended isolation boundary from a virtual machine into its host environment."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-2.4", "title": "Turn indicators into hypotheses", "core": 4, "objective": "2.4", "domain": 2, "type": "security", "requires": ["cert4-2.3"], "lore": "An indicator is evidence to investigate, not automatic proof of compromise. Correlate timing, identities, sources, destinations, process behavior, and business context. A single failure may be a typo; one attempt against hundreds of users may indicate spraying. Different attacks produce different patterns, so use the most specific supported hypothesis. Preserve evidence and apply proportionate containment rather than changing systems blindly.\n\nFIELD NOTES\n\nRansomware — Malware that denies access to data or systems, often through encryption, and demands a payment or concession.\n\nWorm — Malware able to spread between systems without requiring a user to attach it to another program.\n\nTrojan — Malicious functionality disguised as legitimate or desirable software.\n\nRootkit — Software intended to conceal privileged malicious activity or maintain stealthy access at a low system level.\n\nPassword spraying — Trying a small number of common passwords across many accounts to reduce per-account lockout triggers.\n\nCredential stuffing — Reusing stolen username and password pairs against another service.\n\nDistributed denial of service — Using many sources to exhaust a target's resources or overwhelm its ability to serve legitimate users.\n\nOn-path attack — Positioning between communicating endpoints to observe or manipulate traffic.\n\nReplay attack — Reusing a previously captured valid message or authentication exchange to impersonate an authorized action.\n\nImpossible-travel indicator — Logins from locations too distant for plausible travel in the elapsed time; a useful alert requiring VPN and context checks.\n\nPUT IT IN CONTEXT\n\nA virus attaches to other executable content; spyware collects information; a keylogger captures keystrokes; a logic bomb triggers under defined conditions; unwanted bloatware expands attack surface. Physical attacks include forced entry, cloned RFID access, and environmental disruption. Reflected amplification abuses third-party responders in denial-of-service attacks. DNS and wireless manipulation can redirect users. Injection targets interpreters; privilege escalation increases authority. Indicators include locked accounts, concurrent sessions, missing logs, out-of-cycle execution, blocked content, and unusual resource use. Investigate combinations rather than declaring every anomaly malicious.", "example": "At 02:00 a workstation starts renaming many documents, a new process contacts an unfamiliar domain, and a ransom note appears. Taken together these indicators strongly support ransomware. Isolate using the response procedure, preserve relevant evidence, and investigate scope; a scheduled backup alone would not explain the ransom note.", "questions": [{"id": "cert4-2.4-practice-2-4-0", "prompt": "Which concept best fits this description? Malware that denies access to data or systems, often through encryption, and demands a payment or concession.", "explanation": "Ransomware: Malware that denies access to data or systems, often through encryption, and demands a payment or concession. The other choices describe different mechanisms or properties.", "options": ["Rootkit", "Distributed denial of service", "Ransomware", "Worm"], "answer": 2, "tier": 1}, {"id": "cert4-2.4-practice-2-4-1", "prompt": "Which concept best fits this description? Malware able to spread between systems without requiring a user to attach it to another program.", "explanation": "Worm: Malware able to spread between systems without requiring a user to attach it to another program. The other choices describe different mechanisms or properties.", "options": ["On-path attack", "Worm", "Trojan", "Password spraying"], "answer": 1, "tier": 1}, {"id": "cert4-2.4-match-2-4", "prompt": "Match the field notes to their meaning.", "explanation": "Trojan: Malicious functionality disguised as legitimate or desirable software.\nPassword spraying: Trying a small number of common passwords across many accounts to reduce per-account lockout triggers.\nDistributed denial of service: Using many sources to exhaust a target's resources or overwhelm its ability to serve legitimate users.\nReplay attack: Reusing a previously captured valid message or authentication exchange to impersonate an authorized action.", "left": ["Trojan", "Password spraying", "Distributed denial of service", "Replay attack"], "options": ["Using many sources to exhaust a target's resources or overwhelm its ability to serve legitimate users.", "Malicious functionality disguised as legitimate or desirable software.", "Reusing a previously captured valid message or authentication exchange to impersonate an authorized action.", "Trying a small number of common passwords across many accounts to reduce per-account lockout triggers."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-2.4-scenario-2-4-0", "prompt": "Identity log, five-minute window:\n08:00 user01 failure 198.51.100.12\n08:01 user02 failure 198.51.100.12\n08:02 user03 failure 198.51.100.12\nThe same source tries one common password against 300 accounts.\n\nWhich hypothesis best fits the pattern?", "explanation": "A small password set across many users is characteristic of spraying.", "options": ["Password spraying", "A single user's mistyped password", "A database backup"], "answer": 0, "tier": 3}, {"id": "cert4-2.4-scenario-2-4-1", "prompt": "Identity log, five-minute window:\n08:00 user01 failure 198.51.100.12\n08:01 user02 failure 198.51.100.12\n08:02 user03 failure 198.51.100.12\nThe same source tries one common password against 300 accounts.\n\nWhich extra evidence most helps assess impact?", "explanation": "Success and session evidence help determine whether any access was gained.", "options": ["Monitor color settings", "Successful logins and session activity for targeted accounts", "The attacker's claimed job title"], "answer": 1, "tier": 3}, {"id": "cert4-2.4-scenario-2-4-2", "prompt": "Identity log, five-minute window:\n08:00 user01 failure 198.51.100.12\n08:01 user02 failure 198.51.100.12\n08:02 user03 failure 198.51.100.12\nThe same source tries one common password against 300 accounts.\n\nWhich long-term improvement is most appropriate?", "explanation": "Layered identity protections reduce successful guessing without discarding useful evidence.", "options": ["Remove all login telemetry", "Share a universal password", "Use strong authentication, detection, and risk-appropriate rate controls"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-2.5", "title": "Reduce exposure in layers", "core": 4, "objective": "2.5", "domain": 2, "type": "security", "requires": ["cert4-2.4"], "lore": "Mitigation reduces likelihood or impact; it does not necessarily remove the root cause. Prioritize exposed and valuable assets, then combine isolation, controlled access, hardening, patching, and monitoring. Disabling a feature can remove an attack path, while an alert merely tells you the path may have been used. A segmentation rule must be enforced and tested. A diagram dividing two networks has no effect if traffic is still unrestricted.\n\nFIELD NOTES\n\nNetwork segmentation — Dividing a network into separately controlled zones to restrict unnecessary communication and contain compromise.\n\nAccess control list — A rule set permitting or denying operations or traffic according to defined subjects, resources, or network attributes.\n\nApplication allowlisting — Permitting only specifically approved applications or executable identities to run.\n\nHost isolation — Restricting a device's communication to contain a suspected or confirmed compromise.\n\nSecurity patching — Applying a vendor correction to address known defects or vulnerabilities.\n\nLeast privilege — Granting only the access needed for a defined task and removing unnecessary permissions.\n\nConfiguration enforcement — Checking and restoring required settings so a secure baseline does not silently drift.\n\nDecommissioning — Retiring an unnecessary asset and removing its access, data, dependencies, and inventory presence through a controlled process.\n\nService reduction — Disabling unneeded listeners or features to remove avoidable attack paths.\n\nDefault password replacement — Changing supplied secrets before deployment so public or predictable credentials cannot be used.\n\nPUT IT IN CONTEXT\n\nHardening combines approved protocols, encryption, endpoint controls, removal of unnecessary software, and restrictions on default accounts. Monitor deviations and restore secure settings. Allowlisting permits an explicit set; a deny list only blocks specified entries. Isolating a host contains communication but does not itself eradicate persistence.", "example": "A legacy production controller cannot be patched during a manufacturing run. Restrict it to required peers, deny internet access, monitor its segment, and document a supported replacement plan. This lowers exposure but does not make the underlying vulnerability disappear.", "questions": [{"id": "cert4-2.5-practice-2-5-0", "prompt": "Which concept best fits this description? Dividing a network into separately controlled zones to restrict unnecessary communication and contain compromise.", "explanation": "Network segmentation: Dividing a network into separately controlled zones to restrict unnecessary communication and contain compromise. The other choices describe different mechanisms or properties.", "options": ["Host isolation", "Configuration enforcement", "Network segmentation", "Access control list"], "answer": 2, "tier": 1}, {"id": "cert4-2.5-practice-2-5-1", "prompt": "Which concept best fits this description? A rule set permitting or denying operations or traffic according to defined subjects, resources, or network attributes.", "explanation": "Access control list: A rule set permitting or denying operations or traffic according to defined subjects, resources, or network attributes. The other choices describe different mechanisms or properties.", "options": ["Decommissioning", "Access control list", "Application allowlisting", "Security patching"], "answer": 1, "tier": 1}, {"id": "cert4-2.5-match-2-5", "prompt": "Match the field notes to their meaning.", "explanation": "Application allowlisting: Permitting only specifically approved applications or executable identities to run.\nSecurity patching: Applying a vendor correction to address known defects or vulnerabilities.\nConfiguration enforcement: Checking and restoring required settings so a secure baseline does not silently drift.\nService reduction: Disabling unneeded listeners or features to remove avoidable attack paths.", "left": ["Application allowlisting", "Security patching", "Configuration enforcement", "Service reduction"], "options": ["Checking and restoring required settings so a secure baseline does not silently drift.", "Permitting only specifically approved applications or executable identities to run.", "Disabling unneeded listeners or features to remove avoidable attack paths.", "Applying a vendor correction to address known defects or vulnerabilities."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-3.1", "title": "Choose an architecture with clear boundaries", "core": 4, "objective": "3.1", "domain": 3, "type": "security", "requires": [], "lore": "Architecture decides where trust, data, responsibility, and failure boundaries sit. Cloud hosting shifts some responsibilities, but never eliminates the customer's duty to configure access and protect data. Virtual machines share a hypervisor; containers share a host kernel. Embedded and operational systems may prioritize safety, availability, and long support cycles. Select controls that fit the system's constraints instead of installing a general-purpose agent everywhere.\n\nFIELD NOTES\n\nShared responsibility — A model dividing security duties between a cloud provider and customer according to the service used.\n\nInfrastructure as a Service — A cloud model in which the customer commonly manages guest operating systems and applications while the provider manages underlying infrastructure.\n\nSoftware as a Service — A hosted application model in which customers still manage identities, tenant settings, and their use of data.\n\nInfrastructure as code — Defining infrastructure in machine-readable configuration so deployments can be reviewed, reproduced, and versioned.\n\nServerless computing — Running application functions without managing the underlying server instances directly; code, permissions, and data still need protection.\n\nMicroservices — Separating application capabilities into independently deployed services whose inter-service trust and communication need controls.\n\nContainer isolation — Separating application environments while sharing a host kernel, requiring image, runtime, and host security.\n\nAir gap — A physical separation from other networks that reduces remote connectivity but still requires controls for removable media and personnel.\n\nIndustrial control system — Technology that monitors or controls physical processes where safety, deterministic operation, and availability shape security decisions.\n\nReal-time operating system — An operating system designed to meet timing constraints, where predictable response can matter more than general-purpose flexibility.\n\nPUT IT IN CONTEXT\n\nArchitecture tradeoffs include on-premises versus cloud, centralized versus decentralized control, virtualization, network segmentation, and physical isolation. SDN separates control from forwarding. IaC supports review but exposed templates or secrets create new risks. IoT, embedded systems, and ICS/SCADA may have limited patching or monitoring. Evaluate availability, resilience, cost, responsiveness, scalability, power, compute capacity, and supportability together.", "example": "A SaaS provider maintains its application servers, while your organization controls tenant users, roles, and sharing settings. A publicly shared customer folder is still your configuration problem. Read the service agreement and shared-responsibility model before assigning remediation work.", "questions": [{"id": "cert4-3.1-practice-3-1-0", "prompt": "Which concept best fits this description? A model dividing security duties between a cloud provider and customer according to the service used.", "explanation": "Shared responsibility: A model dividing security duties between a cloud provider and customer according to the service used. The other choices describe different mechanisms or properties.", "options": ["Container isolation", "Shared responsibility", "Infrastructure as a Service", "Infrastructure as code"], "answer": 1, "tier": 1}, {"id": "cert4-3.1-practice-3-1-1", "prompt": "Which concept best fits this description? A cloud model in which the customer commonly manages guest operating systems and applications while the provider manages underlying infrastructure.", "explanation": "Infrastructure as a Service: A cloud model in which the customer commonly manages guest operating systems and applications while the provider manages underlying infrastructure. The other choices describe different mechanisms or properties.", "options": ["Infrastructure as a Service", "Software as a Service", "Serverless computing", "Air gap"], "answer": 0, "tier": 1}, {"id": "cert4-3.1-match-3-1", "prompt": "Match the field notes to their meaning.", "explanation": "Software as a Service: A hosted application model in which customers still manage identities, tenant settings, and their use of data.\nServerless computing: Running application functions without managing the underlying server instances directly; code, permissions, and data still need protection.\nContainer isolation: Separating application environments while sharing a host kernel, requiring image, runtime, and host security.\nIndustrial control system: Technology that monitors or controls physical processes where safety, deterministic operation, and availability shape security decisions.", "left": ["Software as a Service", "Serverless computing", "Container isolation", "Industrial control system"], "options": ["Separating application environments while sharing a host kernel, requiring image, runtime, and host security.", "A hosted application model in which customers still manage identities, tenant settings, and their use of data.", "Technology that monitors or controls physical processes where safety, deterministic operation, and availability shape security decisions.", "Running application functions without managing the underlying server instances directly; code, permissions, and data still need protection."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-3.2", "title": "Design the paths traffic may take", "core": 4, "objective": "3.2", "domain": 3, "type": "security", "requires": ["cert4-3.1"], "lore": "A secure network permits required flows and denies unnecessary ones. Place enforcement where it can observe the traffic that matters. A firewall cannot inspect encrypted application content without an appropriate design, and an IDS alert does not block traffic by itself. Consider fail-open versus fail-closed behavior against safety and availability requirements. Remote access should authenticate identities and protect traffic rather than grant unrestricted internal trust.\n\nFIELD NOTES\n\nScreened subnet — A controlled network zone for externally reachable services that separates them from more trusted internal resources.\n\nFirewall rule — A traffic permit or deny decision based on configured attributes such as source, destination, protocol, port, or application.\n\nIntrusion detection system — A monitoring component that detects suspicious traffic or behavior and generates findings without necessarily blocking it.\n\nIntrusion prevention system — An inline security component capable of blocking traffic that matches its prevention policy.\n\nVirtual private network — A protected tunnel over another network, often used to secure remote or site-to-site communications.\n\nZero trust network access — Resource-specific access based on identity and context rather than broad trust granted by joining an internal network.\n\nNetwork access control — Evaluating identity or device condition before permitting a device onto an appropriate network segment.\n\nFail-closed design — Denying access when a security enforcement component fails, preserving restriction at a potential availability cost.\n\nFail-open design — Allowing traffic when an enforcement component fails, favoring continuity while potentially reducing protection.\n\nSecure administration path — A restricted management route using protected protocols and authorized endpoints rather than exposing management interfaces broadly.\n\nPUT IT IN CONTEXT\n\nPlace sensors where they can observe required traffic, using a tap or mirrored port for passive collection or an inline position for prevention. Proxies mediate requests, jump hosts constrain administration, and load balancers distribute service traffic. Use TLS for protected application transport, IPsec for appropriate network tunnels, and secure alternatives to plaintext administration. Port security and 802.1X help constrain endpoint access. A failure-mode decision must consider safety as well as confidentiality.", "example": "A public web server needs HTTPS from the internet and a narrow database connection. Put it in a screened subnet, permit only its required database flow, deny direct internet-to-database access, and log policy violations. Test actual allowed and denied connections after deploying the rules.", "questions": [{"id": "cert4-3.2-practice-3-2-0", "prompt": "Which concept best fits this description? A controlled network zone for externally reachable services that separates them from more trusted internal resources.", "explanation": "Screened subnet: A controlled network zone for externally reachable services that separates them from more trusted internal resources. The other choices describe different mechanisms or properties.", "options": ["Network access control", "Screened subnet", "Firewall rule", "Intrusion prevention system"], "answer": 1, "tier": 1}, {"id": "cert4-3.2-practice-3-2-1", "prompt": "Which concept best fits this description? A traffic permit or deny decision based on configured attributes such as source, destination, protocol, port, or application.", "explanation": "Firewall rule: A traffic permit or deny decision based on configured attributes such as source, destination, protocol, port, or application. The other choices describe different mechanisms or properties.", "options": ["Firewall rule", "Intrusion detection system", "Virtual private network", "Fail-closed design"], "answer": 0, "tier": 1}, {"id": "cert4-3.2-match-3-2", "prompt": "Match the field notes to their meaning.", "explanation": "Intrusion detection system: A monitoring component that detects suspicious traffic or behavior and generates findings without necessarily blocking it.\nVirtual private network: A protected tunnel over another network, often used to secure remote or site-to-site communications.\nNetwork access control: Evaluating identity or device condition before permitting a device onto an appropriate network segment.\nFail-open design: Allowing traffic when an enforcement component fails, favoring continuity while potentially reducing protection.", "left": ["Intrusion detection system", "Virtual private network", "Network access control", "Fail-open design"], "options": ["Evaluating identity or device condition before permitting a device onto an appropriate network segment.", "A monitoring component that detects suspicious traffic or behavior and generates findings without necessarily blocking it.", "Allowing traffic when an enforcement component fails, favoring continuity while potentially reducing protection.", "A protected tunnel over another network, often used to secure remote or site-to-site communications."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-3.2-scenario-3-2-0", "prompt": "First-match firewall. Internet=any; web=192.0.2.10; database=192.0.2.20.\nRequirement: internet → web TCP443, web → database TCP5432; deny everything else.\n\nWhich internet-facing permit meets the requirement?", "explanation": "Only the public web service should be exposed to internet traffic.", "options": ["Allow any → database any port", "Allow any → web TCP443", "Allow any → any TCP5432"], "answer": 1, "tier": 3}, {"id": "cert4-3.2-scenario-3-2-1", "prompt": "First-match firewall. Internet=any; web=192.0.2.10; database=192.0.2.20.\nRequirement: internet → web TCP443, web → database TCP5432; deny everything else.\n\nWhich database permit is narrow enough?", "explanation": "The application host gets only the required database flow.", "options": ["Allow any → database any port", "Allow database → any any port", "Allow web → database TCP5432"], "answer": 2, "tier": 3}, {"id": "cert4-3.2-scenario-3-2-2", "prompt": "First-match firewall. Internet=any; web=192.0.2.10; database=192.0.2.20.\nRequirement: internet → web TCP443, web → database TCP5432; deny everything else.\n\nWhere should a deny-all catch-all go in this policy?", "explanation": "In this first-match policy the required permits precede the catch-all deny.", "options": ["After the narrow required permits", "Before every permit", "It is unnecessary if the web server is encrypted"], "answer": 0, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-3.3", "title": "Protect data throughout its life", "core": 4, "objective": "3.3", "domain": 3, "type": "security", "requires": ["cert4-3.2"], "lore": "Data protection begins with knowing what the information is, where it lives, who owns it, and how long it is needed. Apply controls to data at rest, in transit, and in use. Encryption protects confidentiality only while keys and access remain controlled. Classification expresses sensitivity; residency identifies physical location; sovereignty concerns applicable authority. Minimize collection and retain only what is justified. Masking a display is not the same as encrypting the stored source.\n\nFIELD NOTES\n\nData at rest — Information stored on media, such as files on a disk or records in a database.\n\nData in transit — Information moving between systems or network locations.\n\nData in use — Information being processed, including values in working memory or an active application.\n\nData classification — Assigning sensitivity labels that determine required handling and protection.\n\nData owner — The accountable business role that determines appropriate classification and authorized use of a dataset.\n\nData residency — The geographic location in which information is stored or processed.\n\nData sovereignty — The relationship between information and the legal authority applicable to its location and handling.\n\nData masking — Concealing part of a value in a display or dataset to limit unnecessary disclosure.\n\nData loss prevention — Controls that detect or restrict sensitive information moving through monitored endpoints, storage, or communication channels.\n\nData minimization — Collecting and keeping only information needed for a defined purpose, reducing unnecessary exposure.\n\nPUT IT IN CONTEXT\n\nSensitive data can include personal, financial, health, trade-secret, legal, and intellectual-property information. Labels may distinguish public, private, confidential, restricted, or regulated material according to policy. Geographic restrictions and permission boundaries are different controls. Hashing detects changes; it cannot recover a secret or replace encryption. Masking is useful for display, but the underlying originals still require access controls and lifecycle management.", "example": "A support dashboard must show account status without exposing full payment details. Mask displayed values, restrict access to the underlying records, and minimize retention. Encrypting a disk alone does not prevent an authorized but overprivileged support user from reading a cleartext application response.", "questions": [{"id": "cert4-3.3-practice-3-3-0", "prompt": "Which concept best fits this description? Information stored on media, such as files on a disk or records in a database.", "explanation": "Data at rest: Information stored on media, such as files on a disk or records in a database. The other choices describe different mechanisms or properties.", "options": ["Data sovereignty", "Data at rest", "Data in transit", "Data classification"], "answer": 1, "tier": 1}, {"id": "cert4-3.3-practice-3-3-1", "prompt": "Which concept best fits this description? Information moving between systems or network locations.", "explanation": "Data in transit: Information moving between systems or network locations. The other choices describe different mechanisms or properties.", "options": ["Data in transit", "Data in use", "Data owner", "Data masking"], "answer": 0, "tier": 1}, {"id": "cert4-3.3-match-3-3", "prompt": "Match the field notes to their meaning.", "explanation": "Data in use: Information being processed, including values in working memory or an active application.\nData owner: The accountable business role that determines appropriate classification and authorized use of a dataset.\nData sovereignty: The relationship between information and the legal authority applicable to its location and handling.\nData loss prevention: Controls that detect or restrict sensitive information moving through monitored endpoints, storage, or communication channels.", "left": ["Data in use", "Data owner", "Data sovereignty", "Data loss prevention"], "options": ["The relationship between information and the legal authority applicable to its location and handling.", "Information being processed, including values in working memory or an active application.", "Controls that detect or restrict sensitive information moving through monitored endpoints, storage, or communication channels.", "The accountable business role that determines appropriate classification and authorized use of a dataset."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-3.4", "title": "Design recovery before the outage", "core": 4, "objective": "3.4", "domain": 3, "type": "security", "requires": ["cert4-3.3"], "lore": "Resilience maintains acceptable service through disruption; recovery restores it afterward. Business impact determines priorities and tolerable loss. RTO describes desired restoration time and RPO describes tolerable data loss measured in time. High availability is not a substitute for independent backups: replication can copy deletion or corruption. Test restoration, dependencies, credentials, and communication. A backup that has never been restored is an unproven recovery assumption.\n\nFIELD NOTES\n\nRecovery time objective — The target duration within which a disrupted service should be restored.\n\nRecovery point objective — The maximum tolerable data-loss window measured backward in time from a disruption.\n\nHigh availability — Designing redundant components and failover to maintain service when an individual component fails.\n\nLoad balancing — Distributing work across available resources to improve service capacity or continuity.\n\nHot recovery site — An alternate environment with substantial ready-to-run capability for rapid restoration.\n\nCold recovery site — An alternate location requiring significant equipment or configuration before operations can resume.\n\nImmutable backup — A backup copy protected against modification or deletion for a defined retention period.\n\nOffline backup — A recovery copy disconnected from normal online access paths, reducing exposure to online compromise.\n\nTabletop exercise — A discussion-based rehearsal in which participants walk through decisions and responsibilities for a simulated disruption.\n\nRestoration test — Actually recovering data and services to demonstrate that backups and procedures meet defined recovery needs.\n\nPUT IT IN CONTEXT\n\nWarm sites fall between cold and hot readiness. Geographic separation reduces shared disasters, but regional dependencies still matter. Capacity planning includes power and people as well as compute. Generators and UPS systems support continuity at different timescales. Backups may be full, incremental, differential, snapshots, replicated copies, or transaction logs; evaluate restore dependencies. Practice failover and failback, and test power, platform diversity, recovery credentials, and crisis communications.", "example": "An order system has an RPO of 15 minutes and an RTO of two hours. A daily backup cannot satisfy that RPO. Use an appropriately frequent recoverable copy, test restoring application and data within two hours, and verify that DNS, identity, and network dependencies work.", "questions": [{"id": "cert4-3.4-practice-3-4-0", "prompt": "Which concept best fits this description? The target duration within which a disrupted service should be restored.", "explanation": "Recovery time objective: The target duration within which a disrupted service should be restored. The other choices describe different mechanisms or properties.", "options": ["Immutable backup", "Recovery time objective", "Recovery point objective", "Load balancing"], "answer": 1, "tier": 1}, {"id": "cert4-3.4-practice-3-4-1", "prompt": "Which concept best fits this description? The maximum tolerable data-loss window measured backward in time from a disruption.", "explanation": "Recovery point objective: The maximum tolerable data-loss window measured backward in time from a disruption. The other choices describe different mechanisms or properties.", "options": ["Recovery point objective", "High availability", "Hot recovery site", "Offline backup"], "answer": 0, "tier": 1}, {"id": "cert4-3.4-match-3-4", "prompt": "Match the field notes to their meaning.", "explanation": "High availability: Designing redundant components and failover to maintain service when an individual component fails.\nHot recovery site: An alternate environment with substantial ready-to-run capability for rapid restoration.\nImmutable backup: A backup copy protected against modification or deletion for a defined retention period.\nTabletop exercise: A discussion-based rehearsal in which participants walk through decisions and responsibilities for a simulated disruption.", "left": ["High availability", "Hot recovery site", "Immutable backup", "Tabletop exercise"], "options": ["A backup copy protected against modification or deletion for a defined retention period.", "Designing redundant components and failover to maintain service when an individual component fails.", "A discussion-based rehearsal in which participants walk through decisions and responsibilities for a simulated disruption.", "An alternate environment with substantial ready-to-run capability for rapid restoration."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-3.4-scenario-3-4-0", "prompt": "Orders must lose at most 15 minutes of data and return within 2 hours. Backups currently run once nightly.\n\nWhich objective does a daily-only backup fail to support?", "explanation": "A daily backup can leave much more than 15 minutes of lost data.", "options": ["RPO of 15 minutes", "A display resolution target", "Password length"], "answer": 0, "tier": 3}, {"id": "cert4-3.4-scenario-3-4-1", "prompt": "Orders must lose at most 15 minutes of data and return within 2 hours. Backups currently run once nightly.\n\nWhich action demonstrates the recovery target?", "explanation": "An actual restore verifies recovery capability and elapsed time.", "options": ["Reading a vendor brochure", "Timing an end-to-end restore with dependencies", "Counting backup filenames"], "answer": 1, "tier": 3}, {"id": "cert4-3.4-scenario-3-4-2", "prompt": "Orders must lose at most 15 minutes of data and return within 2 hours. Backups currently run once nightly.\n\nWhy keep a separately protected backup despite replication?", "explanation": "Redundant live copies can reproduce the same damaging change.", "options": ["Replication always encrypts originals", "Replication replaces every recovery plan", "Replication may copy corruption or deletion"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.1", "title": "Harden systems for their actual role", "core": 4, "objective": "4.1", "domain": 4, "type": "security", "requires": [], "lore": "Hardening reduces unnecessary capability and applies an appropriate secure baseline. Begin with a supported platform, remove unneeded software, limit management access, and verify configuration drift. Mobile, wireless, cloud, IoT, and embedded systems need different controls. Secure development includes validation, testing, patching, and controlled deployment. Never apply a generic baseline blindly to safety-critical equipment; test compatibility and required functions.\n\nFIELD NOTES\n\nSecure baseline — A documented set of approved configuration settings for a defined class of systems.\n\nConfiguration drift — A deployed system's settings moving away from its required baseline over time.\n\nMobile device management — Central enforcement of mobile device settings, inventory, restrictions, and remote administrative actions.\n\nFull-disk encryption — Protecting stored disk contents against unauthorized offline access when the required unlock key is unavailable.\n\nSecure boot — Verifying trusted signatures during the boot chain to help prevent unauthorized boot components.\n\nWireless enterprise authentication — Using centrally managed user or device identities for wireless access rather than sharing one password among all users.\n\nInput validation — Checking whether input meets expected format, size, type, or business rules before processing it.\n\nStatic application analysis — Examining source or compiled code for issues without executing the application under test.\n\nDynamic application analysis — Testing a running application to observe vulnerabilities or insecure behavior during execution.\n\nSandboxing — Executing untrusted or risky code within a constrained environment to limit its ability to affect other resources.\n\nPUT IT IN CONTEXT\n\nBaseline endpoints, servers, network devices, cloud resources, embedded devices, and IoT according to role. Wireless hardening includes WPA3 where supported, appropriate channels, transmit power, antenna placement, and authenticated enterprise access. Mobile deployment models include organization-owned and personally owned devices with different privacy boundaries. Secure coding combines validation, output encoding, safe queries, dependency review, testing, code signing, and controlled releases. Avoid trusting an image merely because it starts successfully.", "example": "A new kiosk needs a browser and one business application. Remove unused services, limit application execution, use a restricted account, protect storage, configure central updates, and validate that the kiosk can still perform its job. Document exceptions instead of disabling the baseline silently.", "questions": [{"id": "cert4-4.1-practice-4-1-0", "prompt": "Which concept best fits this description? A documented set of approved configuration settings for a defined class of systems.", "explanation": "Secure baseline: A documented set of approved configuration settings for a defined class of systems. The other choices describe different mechanisms or properties.", "options": ["Secure baseline", "Configuration drift", "Full-disk encryption", "Input validation"], "answer": 0, "tier": 1}, {"id": "cert4-4.1-practice-4-1-1", "prompt": "Which concept best fits this description? A deployed system's settings moving away from its required baseline over time.", "explanation": "Configuration drift: A deployed system's settings moving away from its required baseline over time. The other choices describe different mechanisms or properties.", "options": ["Mobile device management", "Secure boot", "Static application analysis", "Configuration drift"], "answer": 3, "tier": 1}, {"id": "cert4-4.1-match-4-1", "prompt": "Match the field notes to their meaning.", "explanation": "Mobile device management: Central enforcement of mobile device settings, inventory, restrictions, and remote administrative actions.\nSecure boot: Verifying trusted signatures during the boot chain to help prevent unauthorized boot components.\nInput validation: Checking whether input meets expected format, size, type, or business rules before processing it.\nDynamic application analysis: Testing a running application to observe vulnerabilities or insecure behavior during execution.", "left": ["Mobile device management", "Secure boot", "Input validation", "Dynamic application analysis"], "options": ["Checking whether input meets expected format, size, type, or business rules before processing it.", "Central enforcement of mobile device settings, inventory, restrictions, and remote administrative actions.", "Testing a running application to observe vulnerabilities or insecure behavior during execution.", "Verifying trusted signatures during the boot chain to help prevent unauthorized boot components."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.2", "title": "Manage assets from arrival to retirement", "core": 4, "objective": "4.2", "domain": 4, "type": "security", "requires": ["cert4-4.1"], "lore": "You cannot consistently protect assets you cannot identify. Inventory hardware, software, data, ownership, location, sensitivity, and support state. Procurement and assignment establish responsibility, while monitoring keeps the inventory useful. Disposal must address data as well as equipment. Deleting a file or formatting a drive may leave recoverable data. Choose sanitization based on media, sensitivity, reuse, and verifiable results.\n\nFIELD NOTES\n\nAsset inventory — A maintained record of hardware, software, or data resources and their relevant management attributes.\n\nAsset ownership assignment — Naming an accountable role responsible for an asset's appropriate use and management.\n\nAsset discovery — Finding devices, applications, or data that exist in the environment so unmanaged resources become visible.\n\nProcurement control — Applying security requirements when acquiring technology, including support, authenticity, and lifecycle needs.\n\nAsset tagging — Applying an identifier that links a physical or logical item to its inventory record.\n\nData retention schedule — A defined period and disposal rule for keeping information based on business and applicable obligations.\n\nMedia sanitization — Rendering target data infeasible to recover using an approved clear, purge, or destroy method suitable for the medium.\n\nCryptographic erase — Sanitizing appropriately encrypted data by securely eliminating the keys needed to decrypt it, subject to implementation requirements.\n\nDestruction verification — Recording evidence that a disposal method was completed effectively for the intended media.\n\nLicense tracking — Maintaining software entitlement and deployment information to support compliant and managed use.\n\nPUT IT IN CONTEXT\n\nRecord purchase, receipt, deployment, assignment, tracking, enumeration, maintenance, and end of life. Use sensitivity and business function to prioritize protection. Clearing, purging, cryptographic erase, and physical destruction have different applicability; follow media-specific approved procedures and verify completion. A certificate of destruction is evidence to retain, not a substitute for validating the supplier and method.", "example": "A laptop changes departments. Update its owner and inventory, remove the former user's access and data using an approved process, rebuild to baseline, and confirm the new assignment. At final retirement, verify sanitization and retain evidence before transferring the device outside organizational control.", "questions": [{"id": "cert4-4.2-practice-4-2-0", "prompt": "Which concept best fits this description? A maintained record of hardware, software, or data resources and their relevant management attributes.", "explanation": "Asset inventory: A maintained record of hardware, software, or data resources and their relevant management attributes. The other choices describe different mechanisms or properties.", "options": ["Asset inventory", "Asset ownership assignment", "Procurement control", "Media sanitization"], "answer": 0, "tier": 1}, {"id": "cert4-4.2-practice-4-2-1", "prompt": "Which concept best fits this description? Naming an accountable role responsible for an asset's appropriate use and management.", "explanation": "Asset ownership assignment: Naming an accountable role responsible for an asset's appropriate use and management. The other choices describe different mechanisms or properties.", "options": ["Asset discovery", "Asset tagging", "Cryptographic erase", "Asset ownership assignment"], "answer": 3, "tier": 1}, {"id": "cert4-4.2-match-4-2", "prompt": "Match the field notes to their meaning.", "explanation": "Asset discovery: Finding devices, applications, or data that exist in the environment so unmanaged resources become visible.\nAsset tagging: Applying an identifier that links a physical or logical item to its inventory record.\nMedia sanitization: Rendering target data infeasible to recover using an approved clear, purge, or destroy method suitable for the medium.\nDestruction verification: Recording evidence that a disposal method was completed effectively for the intended media.", "left": ["Asset discovery", "Asset tagging", "Media sanitization", "Destruction verification"], "options": ["Rendering target data infeasible to recover using an approved clear, purge, or destroy method suitable for the medium.", "Finding devices, applications, or data that exist in the environment so unmanaged resources become visible.", "Recording evidence that a disposal method was completed effectively for the intended media.", "Applying an identifier that links a physical or logical item to its inventory record."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.3", "title": "Make vulnerability work a cycle", "core": 4, "objective": "4.3", "domain": 4, "type": "security", "requires": ["cert4-4.2"], "lore": "Vulnerability management includes discovering assets, identifying weaknesses, prioritizing risk, applying treatments, and verifying the result. A severity score is an input, not the complete business decision. Exposure, known exploitation, asset importance, and control coverage can outweigh raw severity. Authenticated scanning can inspect configuration and patch state that an unauthenticated network scan cannot see. Retest after remediation and document accepted exceptions with owners and expiry.\n\nFIELD NOTES\n\nAuthenticated vulnerability scan — A scan using authorized credentials to inspect local configuration, installed software, and patch details.\n\nUnauthenticated vulnerability scan — A scan observing an asset from an external perspective without logging into the target.\n\nCVSS — A standardized way to express technical vulnerability severity, which must be combined with environmental context.\n\nCVE identifier — A common identifier for a publicly cataloged vulnerability, enabling tools and reports to refer to the same issue.\n\nFalse positive — A finding that incorrectly indicates a vulnerability or malicious condition exists.\n\nFalse negative — A missed finding in which a vulnerability or malicious condition exists but is not detected.\n\nRisk-based prioritization — Ordering remediation according to business impact, exposure, exploitation likelihood, and relevant controls.\n\nCompensating mitigation — Reducing exposure or impact when the underlying vulnerability cannot yet be removed.\n\nRemediation verification — Retesting to establish that a corrective action actually resolved the identified issue.\n\nThreat intelligence — Information about threats and adversary behavior used to inform detection, prioritization, or response.\n\nPUT IT IN CONTEXT\n\nDiscovery can include scanning, penetration testing, code review, disclosure programs, and threat-intelligence sources. Validate findings before acting. Communicate critical issues to accountable owners, track patching and configuration changes, and document exceptions. A risk acceptance needs authorization and periodic review. Rescanning or another appropriate test establishes whether remediation worked.", "example": "An internet-facing payment server has a moderately rated vulnerability actively exploited in the wild. An isolated test machine has a higher raw score but no useful data. Prioritize the exposed payment system using exploitability, business impact, and exposure, then verify the fix rather than closing the ticket on deployment alone.", "questions": [{"id": "cert4-4.3-practice-4-3-0", "prompt": "Which concept best fits this description? A scan using authorized credentials to inspect local configuration, installed software, and patch details.", "explanation": "Authenticated vulnerability scan: A scan using authorized credentials to inspect local configuration, installed software, and patch details. The other choices describe different mechanisms or properties.", "options": ["Authenticated vulnerability scan", "Unauthenticated vulnerability scan", "CVE identifier", "Risk-based prioritization"], "answer": 0, "tier": 1}, {"id": "cert4-4.3-practice-4-3-1", "prompt": "Which concept best fits this description? A scan observing an asset from an external perspective without logging into the target.", "explanation": "Unauthenticated vulnerability scan: A scan observing an asset from an external perspective without logging into the target. The other choices describe different mechanisms or properties.", "options": ["CVSS", "False positive", "Compensating mitigation", "Unauthenticated vulnerability scan"], "answer": 3, "tier": 1}, {"id": "cert4-4.3-match-4-3", "prompt": "Match the field notes to their meaning.", "explanation": "CVSS: A standardized way to express technical vulnerability severity, which must be combined with environmental context.\nFalse positive: A finding that incorrectly indicates a vulnerability or malicious condition exists.\nRisk-based prioritization: Ordering remediation according to business impact, exposure, exploitation likelihood, and relevant controls.\nRemediation verification: Retesting to establish that a corrective action actually resolved the identified issue.", "left": ["CVSS", "False positive", "Risk-based prioritization", "Remediation verification"], "options": ["Ordering remediation according to business impact, exposure, exploitation likelihood, and relevant controls.", "A standardized way to express technical vulnerability severity, which must be combined with environmental context.", "Retesting to establish that a corrective action actually resolved the identified issue.", "A finding that incorrectly indicates a vulnerability or malicious condition exists."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-4.3-scenario-4-3-0", "prompt": "Server A: internet-facing payment server; known active exploitation; severity 7.5.\nServer B: isolated test box; no sensitive data; severity 9.8.\n\nWhich should normally be prioritized given these facts?", "explanation": "Severity is one input; the stated exposure and exploitation make A urgent.", "options": ["Server B solely because 9.8 is larger", "Neither; severity is irrelevant", "Server A because exposure, exploitation, and business impact elevate risk"], "answer": 2, "tier": 3}, {"id": "cert4-4.3-scenario-4-3-1", "prompt": "Server A: internet-facing payment server; known active exploitation; severity 7.5.\nServer B: isolated test box; no sensitive data; severity 9.8.\n\nWhat closes the technical remediation loop?", "explanation": "Verification establishes that the weakness was actually addressed.", "options": ["Retest the affected condition after the fix", "Mark the ticket complete when a download starts", "Wait for an attacker to try again"], "answer": 0, "tier": 3}, {"id": "cert4-4.3-scenario-4-3-2", "prompt": "Server A: internet-facing payment server; known active exploitation; severity 7.5.\nServer B: isolated test box; no sensitive data; severity 9.8.\n\nIf A cannot be patched immediately, what is sensible?", "explanation": "Reduce exposure and set accountable follow-up while arranging a supported fix.", "options": ["Ignore the issue indefinitely", "Apply scoped compensating restrictions and track an accountable exception", "Publish its administrator password"], "answer": 1, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.4", "title": "Turn telemetry into useful signals", "core": 4, "objective": "4.4", "domain": 4, "type": "security", "requires": ["cert4-4.3"], "lore": "Monitoring converts observations into decisions. Collect useful events, normalize time and fields, centralize them with appropriate access, and tune detections against real behavior. A SIEM correlates data; it cannot repair missing telemetry. Protect the logging path and retention so an attacker cannot easily erase the record. Alerts need triage, ownership, and an escalation path. Noise matters because analysts have finite attention.\n\nFIELD NOTES\n\nSIEM — A system that collects and analyzes security events from multiple sources to support detection and investigation.\n\nLog aggregation — Centralizing records from multiple systems so analysts can search and correlate them.\n\nEvent normalization — Converting different event formats into consistent fields for meaningful correlation.\n\nTime synchronization — Keeping system clocks aligned so sequences across different log sources can be reconstructed.\n\nAlert tuning — Adjusting detection criteria and exclusions to improve useful signal while avoiding unjustified blind spots.\n\nBaseline behavior — An established pattern of expected activity used to identify meaningful deviations.\n\nSecurity alert triage — Assessing a finding's credibility, severity, context, and required next action.\n\nFile integrity monitoring — Detecting changes to monitored files by comparing them with an expected state.\n\nAgent-based monitoring — Using software installed on a target to collect local telemetry or enforce security functions.\n\nLog retention — Keeping event records for a defined period to support operations, investigations, and applicable obligations.\n\nPUT IT IN CONTEXT\n\nCollect system, endpoint, network, application, and security-tool telemetry. SNMP monitoring, NetFlow, packet analysis, and vulnerability tools answer different questions. Tune alerts, generate reports, archive needed evidence, and distinguish alerts from confirmed incidents. Protect collection credentials and validate data sources, timestamps, and retention.", "example": "A cloud audit event records a new privileged role assignment and an identity log records a login from a new device. Correlating them is stronger than alerting on either in isolation. Confirm timestamps and the approved change calendar before deciding whether the sequence is malicious.", "questions": [{"id": "cert4-4.4-practice-4-4-0", "prompt": "Which concept best fits this description? A system that collects and analyzes security events from multiple sources to support detection and investigation.", "explanation": "SIEM: A system that collects and analyzes security events from multiple sources to support detection and investigation. The other choices describe different mechanisms or properties.", "options": ["SIEM", "Log aggregation", "Time synchronization", "Security alert triage"], "answer": 0, "tier": 1}, {"id": "cert4-4.4-practice-4-4-1", "prompt": "Which concept best fits this description? Centralizing records from multiple systems so analysts can search and correlate them.", "explanation": "Log aggregation: Centralizing records from multiple systems so analysts can search and correlate them. The other choices describe different mechanisms or properties.", "options": ["Event normalization", "Alert tuning", "File integrity monitoring", "Log aggregation"], "answer": 3, "tier": 1}, {"id": "cert4-4.4-match-4-4", "prompt": "Match the field notes to their meaning.", "explanation": "Event normalization: Converting different event formats into consistent fields for meaningful correlation.\nAlert tuning: Adjusting detection criteria and exclusions to improve useful signal while avoiding unjustified blind spots.\nSecurity alert triage: Assessing a finding's credibility, severity, context, and required next action.\nAgent-based monitoring: Using software installed on a target to collect local telemetry or enforce security functions.", "left": ["Event normalization", "Alert tuning", "Security alert triage", "Agent-based monitoring"], "options": ["Assessing a finding's credibility, severity, context, and required next action.", "Converting different event formats into consistent fields for meaningful correlation.", "Using software installed on a target to collect local telemetry or enforce security functions.", "Adjusting detection criteria and exclusions to improve useful signal while avoiding unjustified blind spots."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.5", "title": "Operate enterprise defenses deliberately", "core": 4, "objective": "4.5", "domain": 4, "type": "security", "requires": ["cert4-4.4"], "lore": "Security tools enforce policy only when their scope, placement, and configuration fit the risk. Email filtering, endpoint protection, DNS controls, and firewalls act on different evidence. Secure protocols protect transport, while application filters inspect application behavior. Understand default-deny rules and first-match behavior where configured. Test permitted and blocked flows, maintain rule ownership, and remove stale exceptions.\n\nFIELD NOTES\n\nWeb application firewall — A control filtering application-layer web requests to reduce exposure to certain web attacks.\n\nEndpoint detection and response — Endpoint telemetry and response capabilities used to investigate and contain suspicious host behavior.\n\nDNS filtering — Blocking or controlling name resolution for destinations identified by policy as unwanted or malicious.\n\nSecure email gateway — Filtering inbound or outbound email for threats, unwanted content, or policy violations.\n\nSPF — A DNS-published policy identifying servers authorized to send mail for a domain.\n\nDKIM — A domain-associated digital signature that lets receivers verify signed email content has not changed.\n\nDMARC — A domain policy and reporting mechanism using alignment with SPF or DKIM results to guide email handling.\n\nDefault-deny rule — A policy that rejects traffic or activity unless an explicit permitted case applies.\n\nFirst-match processing — Evaluating rules in order and applying the first matching rule in a rule set configured for that behavior.\n\nData egress control — Restricting or inspecting outbound transfers to reduce unauthorized data leaving an environment.\n\nPUT IT IN CONTEXT\n\nEnterprise controls also include firewalls with application awareness, secure web gateways, network segmentation, operating-system protections, email attachment and content analysis, and endpoint application restrictions. Secure protocols and certificates support protected sessions. UTM combines several functions but still needs appropriate placement and policy. Rules should have owners, documented purposes, and review dates.", "example": "A first-match firewall has 'allow any to database' above 'deny internet to database'. The broad permit wins. Replace the broad access with narrow required application flows and an appropriate final deny. Merely adding another deny at the bottom will not fix the ordering problem.", "questions": [{"id": "cert4-4.5-practice-4-5-0", "prompt": "Which concept best fits this description? A control filtering application-layer web requests to reduce exposure to certain web attacks.", "explanation": "Web application firewall: A control filtering application-layer web requests to reduce exposure to certain web attacks. The other choices describe different mechanisms or properties.", "options": ["Web application firewall", "Endpoint detection and response", "Secure email gateway", "DMARC"], "answer": 0, "tier": 1}, {"id": "cert4-4.5-practice-4-5-1", "prompt": "Which concept best fits this description? Endpoint telemetry and response capabilities used to investigate and contain suspicious host behavior.", "explanation": "Endpoint detection and response: Endpoint telemetry and response capabilities used to investigate and contain suspicious host behavior. The other choices describe different mechanisms or properties.", "options": ["DNS filtering", "SPF", "Default-deny rule", "Endpoint detection and response"], "answer": 3, "tier": 1}, {"id": "cert4-4.5-match-4-5", "prompt": "Match the field notes to their meaning.", "explanation": "DNS filtering: Blocking or controlling name resolution for destinations identified by policy as unwanted or malicious.\nSPF: A DNS-published policy identifying servers authorized to send mail for a domain.\nDMARC: A domain policy and reporting mechanism using alignment with SPF or DKIM results to guide email handling.\nFirst-match processing: Evaluating rules in order and applying the first matching rule in a rule set configured for that behavior.", "left": ["DNS filtering", "SPF", "DMARC", "First-match processing"], "options": ["A domain policy and reporting mechanism using alignment with SPF or DKIM results to guide email handling.", "Blocking or controlling name resolution for destinations identified by policy as unwanted or malicious.", "Evaluating rules in order and applying the first matching rule in a rule set configured for that behavior.", "A DNS-published policy identifying servers authorized to send mail for a domain."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-4.5-scenario-4-5-0", "prompt": "First-match rules:\n1 ALLOW any → database TCP5432\n2 DENY internet → database any\n3 DENY any → any\nA connection from the internet to the database succeeds.\n\nWhy does the connection succeed?", "explanation": "First-match processing applies rule 1 and stops evaluating this connection.", "options": ["The first permit matches before the deny", "The database port cannot be filtered", "Deny rules always execute first"], "answer": 0, "tier": 3}, {"id": "cert4-4.5-scenario-4-5-1", "prompt": "First-match rules:\n1 ALLOW any → database TCP5432\n2 DENY internet → database any\n3 DENY any → any\nA connection from the internet to the database succeeds.\n\nWhat is the best rule change?", "explanation": "A scoped source permit addresses the overly broad earlier match.", "options": ["Add another deny after rule 3", "Replace rule 1 with only the required application source permit", "Allow all encrypted traffic to any database"], "answer": 1, "tier": 3}, {"id": "cert4-4.5-scenario-4-5-2", "prompt": "First-match rules:\n1 ALLOW any → database TCP5432\n2 DENY internet → database any\n3 DENY any → any\nA connection from the internet to the database succeeds.\n\nWhat validates the change?", "explanation": "Positive and negative traffic tests establish intended enforcement.", "options": ["Check that the rule name sounds strict", "Only inspect the diagram", "Test both the required application flow and the forbidden internet flow"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.6", "title": "Give identities the access they need", "core": 4, "objective": "4.6", "domain": 4, "type": "security", "requires": ["cert4-4.5"], "lore": "Identity management covers onboarding, changes, and timely offboarding as well as sign-in. Authentication establishes identity; authorization determines allowed actions. Two passwords are two instances of the same factor, not multi-factor authentication. Prefer phishing-resistant authentication where feasible. Use roles, attributes, access reviews, and privileged session controls to constrain authority. Service accounts need ownership, scoped privileges, and lifecycle management too.\n\nFIELD NOTES\n\nMulti-factor authentication — Combining evidence from different factor categories, such as a password and possession of a security key.\n\nSingle sign-on — Allowing one authenticated session to access multiple authorized services through a shared identity system.\n\nFederation — Establishing trust between identity systems so one domain can accept identity assertions from another.\n\nRole-based access control — Assigning permissions through job or function roles rather than individually for every user.\n\nAttribute-based access control — Making access decisions from attributes such as user department, device condition, resource label, and time.\n\nDiscretionary access control — Allowing an authorized resource owner to decide access permissions within the system's policy.\n\nMandatory access control — Enforcing centrally defined labels and access rules that ordinary resource owners cannot freely override.\n\nPrivileged access management — Controlling elevated credentials and sessions through approval, monitoring, vaulting, and limited scope.\n\nJust-in-time access — Granting required privileges only for an approved limited period rather than leaving them permanently assigned.\n\nAccess recertification — Periodically reviewing permissions with accountable owners to remove unnecessary or inappropriate access.\n\nPUT IT IN CONTEXT\n\nProvision, modify, disable, and remove accounts according to lifecycle events. Authentication factors include knowledge, possession, and inherence; location and behavior supply context rather than magically creating a secret. Federation protocols such as SAML carry assertions, OAuth delegates authorization, and OpenID Connect adds identity. Biometrics introduce accuracy and privacy tradeoffs. Password managers, lockout/rate controls, secure recovery, privileged vaults, and time-limited grants all support identity protection.", "example": "An employee transfers from payroll to marketing. Add the new role only after approval and remove payroll access; simply accumulating both creates privilege creep. A just-in-time administrative grant can expire automatically after a maintenance task rather than becoming permanent.", "questions": [{"id": "cert4-4.6-practice-4-6-0", "prompt": "Which concept best fits this description? Combining evidence from different factor categories, such as a password and possession of a security key.", "explanation": "Multi-factor authentication: Combining evidence from different factor categories, such as a password and possession of a security key. The other choices describe different mechanisms or properties.", "options": ["Multi-factor authentication", "Single sign-on", "Role-based access control", "Mandatory access control"], "answer": 0, "tier": 1}, {"id": "cert4-4.6-practice-4-6-1", "prompt": "Which concept best fits this description? Allowing one authenticated session to access multiple authorized services through a shared identity system.", "explanation": "Single sign-on: Allowing one authenticated session to access multiple authorized services through a shared identity system. The other choices describe different mechanisms or properties.", "options": ["Federation", "Attribute-based access control", "Privileged access management", "Single sign-on"], "answer": 3, "tier": 1}, {"id": "cert4-4.6-match-4-6", "prompt": "Match the field notes to their meaning.", "explanation": "Federation: Establishing trust between identity systems so one domain can accept identity assertions from another.\nAttribute-based access control: Making access decisions from attributes such as user department, device condition, resource label, and time.\nMandatory access control: Enforcing centrally defined labels and access rules that ordinary resource owners cannot freely override.\nJust-in-time access: Granting required privileges only for an approved limited period rather than leaving them permanently assigned.", "left": ["Federation", "Attribute-based access control", "Mandatory access control", "Just-in-time access"], "options": ["Enforcing centrally defined labels and access rules that ordinary resource owners cannot freely override.", "Establishing trust between identity systems so one domain can accept identity assertions from another.", "Granting required privileges only for an approved limited period rather than leaving them permanently assigned.", "Making access decisions from attributes such as user department, device condition, resource label, and time."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-4.6-scenario-4-6-0", "prompt": "Jordan moves from payroll to marketing. Their old group grants salary exports. Their new role needs campaign reports only.\n\nWhat should the access workflow do?", "explanation": "A transfer should remove obsolete access, not just add permissions.", "options": ["Keep every old permission forever", "Remove unneeded payroll rights and approve marketing rights", "Give domain admin to avoid access tickets"], "answer": 1, "tier": 3}, {"id": "cert4-4.6-scenario-4-6-1", "prompt": "Jordan moves from payroll to marketing. Their old group grants salary exports. Their new role needs campaign reports only.\n\nJordan needs one hour of approved elevated access next week. Choose the mechanism.", "explanation": "A limited approved grant reduces standing privilege.", "options": ["A permanently shared admin password", "An unmonitored local account", "Just-in-time privileged access with expiry"], "answer": 2, "tier": 3}, {"id": "cert4-4.6-scenario-4-6-2", "prompt": "Jordan moves from payroll to marketing. Their old group grants salary exports. Their new role needs campaign reports only.\n\nWhich authentication pair uses distinct factors?", "explanation": "Knowledge plus possession spans distinct categories; two knowledge secrets do not.", "options": ["Password plus a hardware security key", "Two different passwords", "Password plus a second PIN"], "answer": 0, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.7", "title": "Automate with guardrails", "core": 4, "objective": "4.7", "domain": 4, "type": "security", "requires": ["cert4-4.6"], "lore": "Automation runs repeatable steps; orchestration connects steps across tools. Both can reduce delay and human error, but both can amplify a bad decision. Scope service credentials, validate inputs, record actions, and plan failure behavior. Use human approval for actions where uncertainty or impact warrants it. A playbook that disables every account matching a noisy alert can become a denial-of-service mechanism.\n\nFIELD NOTES\n\nSecurity orchestration — Coordinating a security workflow across multiple tools and systems.\n\nAutomation playbook — A defined set of machine-executed actions triggered by an event or authorized request.\n\nAPI integration — Connecting systems through documented programmatic interfaces to exchange data or request actions.\n\nHuman approval gate — Pausing an automated workflow for an accountable person to authorize a consequential action.\n\nService account scoping — Limiting an automation identity to only the permissions and resources required by its workflow.\n\nIdempotent action — An operation designed so repeating the same request does not produce additional unintended effects.\n\nAutomation audit trail — A record of workflow inputs, decisions, actions, and outcomes for later review.\n\nWorkflow rollback — A planned way to undo or compensate for automated changes when the workflow causes an unacceptable outcome.\n\nConfiguration provisioning — Automatically establishing approved system settings or resources in a repeatable manner.\n\nAutomation blast radius — The extent of damage or disruption a faulty automated action could cause across its reachable environment.\n\nPUT IT IN CONTEXT\n\nUse automation for user/resource provisioning, guardrails, ticket enrichment, integration, and response where authorized. Benefits include speed, consistency, and staff efficiency. Risks include complexity, privilege concentration, single points of failure, technical debt, and support gaps. Validate error handling, rate limits, repeat execution, monitoring, and a way to stop a runaway workflow.", "example": "A phishing workflow parses a reported message, checks indicators, and opens a case automatically. Quarantining one known malicious message may be safe under an approved policy; disabling an executive account based on a weak keyword should require stronger evidence or review. Log decisions and provide recovery.", "questions": [{"id": "cert4-4.7-practice-4-7-0", "prompt": "Which concept best fits this description? Coordinating a security workflow across multiple tools and systems.", "explanation": "Security orchestration: Coordinating a security workflow across multiple tools and systems. The other choices describe different mechanisms or properties.", "options": ["Security orchestration", "Automation playbook", "Human approval gate", "Automation audit trail"], "answer": 0, "tier": 1}, {"id": "cert4-4.7-practice-4-7-1", "prompt": "Which concept best fits this description? A defined set of machine-executed actions triggered by an event or authorized request.", "explanation": "Automation playbook: A defined set of machine-executed actions triggered by an event or authorized request. The other choices describe different mechanisms or properties.", "options": ["API integration", "Service account scoping", "Workflow rollback", "Automation playbook"], "answer": 3, "tier": 1}, {"id": "cert4-4.7-match-4-7", "prompt": "Match the field notes to their meaning.", "explanation": "API integration: Connecting systems through documented programmatic interfaces to exchange data or request actions.\nService account scoping: Limiting an automation identity to only the permissions and resources required by its workflow.\nAutomation audit trail: A record of workflow inputs, decisions, actions, and outcomes for later review.\nConfiguration provisioning: Automatically establishing approved system settings or resources in a repeatable manner.", "left": ["API integration", "Service account scoping", "Automation audit trail", "Configuration provisioning"], "options": ["A record of workflow inputs, decisions, actions, and outcomes for later review.", "Connecting systems through documented programmatic interfaces to exchange data or request actions.", "Automatically establishing approved system settings or resources in a repeatable manner.", "Limiting an automation identity to only the permissions and resources required by its workflow."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.8", "title": "Respond with evidence and coordination", "core": 4, "objective": "4.8", "domain": 4, "type": "security", "requires": ["cert4-4.7"], "lore": "Incident response is coordinated risk management under uncertainty. Establish authority, communication channels, tools, and escalation before an incident. Analyze findings, contain impact, remove the cause, restore safely, and improve from lessons learned. These activities can overlap; do not treat a phase list as a reason to delay urgent containment. NIST's newer guidance integrates response across the CSF, while the course also teaches the phase vocabulary used by this exam blueprint.\n\nFIELD NOTES\n\nIncident preparation — Establishing roles, tools, plans, contacts, training, and authority before a security incident occurs.\n\nIncident analysis — Assessing evidence to determine whether an incident exists, what happened, and how far its effects extend.\n\nContainment — Limiting ongoing damage or spread while preserving options for investigation and recovery.\n\nEradication — Removing malicious artifacts, persistence, and exploited causes from affected systems.\n\nRecovery — Restoring services to an acceptable state and monitoring to confirm safe operation.\n\nLessons learned — Reviewing an incident to identify improvements to controls, procedures, detection, and coordination.\n\nChain of custody — Documenting who controlled evidence, when it changed hands, and how it was handled.\n\nLegal hold — A directive to preserve potentially relevant information rather than dispose of it through normal retention rules.\n\nIncident escalation — Moving an incident to the appropriate authority or response capability according to impact and policy.\n\nThreat hunting — Proactively searching for evidence of adversary activity rather than waiting only for an automated alert.\n\nPUT IT IN CONTEXT\n\nPrepare and test playbooks through tabletop and simulation exercises. Preserve forensic copies and volatile evidence when appropriate without delaying necessary safety or containment actions. Establish who communicates internally, to customers, to counsel, and to authorities under applicable policy. NIST SP 800-61 Rev. 3 supersedes the older phase-centric guide, so learn the exam terms while recognizing that real response is integrated and iterative.", "example": "An endpoint is actively encrypting a shared drive. Follow the approved containment process to restrict the endpoint's access while preserving evidence where feasible. Do not start by deleting logs or reinstalling every system. Determine scope, remove persistence, restore from a verified clean source, and monitor for recurrence.", "questions": [{"id": "cert4-4.8-practice-4-8-0", "prompt": "Which concept best fits this description? Establishing roles, tools, plans, contacts, training, and authority before a security incident occurs.", "explanation": "Incident preparation: Establishing roles, tools, plans, contacts, training, and authority before a security incident occurs. The other choices describe different mechanisms or properties.", "options": ["Incident preparation", "Incident analysis", "Eradication", "Chain of custody"], "answer": 0, "tier": 1}, {"id": "cert4-4.8-practice-4-8-1", "prompt": "Which concept best fits this description? Assessing evidence to determine whether an incident exists, what happened, and how far its effects extend.", "explanation": "Incident analysis: Assessing evidence to determine whether an incident exists, what happened, and how far its effects extend. The other choices describe different mechanisms or properties.", "options": ["Containment", "Recovery", "Legal hold", "Incident analysis"], "answer": 3, "tier": 1}, {"id": "cert4-4.8-match-4-8", "prompt": "Match the field notes to their meaning.", "explanation": "Containment: Limiting ongoing damage or spread while preserving options for investigation and recovery.\nRecovery: Restoring services to an acceptable state and monitoring to confirm safe operation.\nChain of custody: Documenting who controlled evidence, when it changed hands, and how it was handled.\nIncident escalation: Moving an incident to the appropriate authority or response capability according to impact and policy.", "left": ["Containment", "Recovery", "Chain of custody", "Incident escalation"], "options": ["Documenting who controlled evidence, when it changed hands, and how it was handled.", "Limiting ongoing damage or spread while preserving options for investigation and recovery.", "Moving an incident to the appropriate authority or response capability according to impact and policy.", "Restoring services to an acceptable state and monitoring to confirm safe operation."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-4.8-scenario-4-8-0", "prompt": "A workstation is actively encrypting a shared folder. The response plan authorizes endpoint isolation. Relevant logs and volatile evidence may be useful.\n\nWhat is the appropriate immediate action?", "explanation": "Ongoing harm warrants authorized containment while coordinating evidence needs.", "options": ["Wait for the weekly meeting", "Delete all logs to save space", "Use approved containment to limit continuing damage"], "answer": 2, "tier": 3}, {"id": "cert4-4.8-scenario-4-8-1", "prompt": "A workstation is actively encrypting a shared folder. The response plan authorizes endpoint isolation. Relevant logs and volatile evidence may be useful.\n\nBefore restoring normal access, what must be addressed?", "explanation": "Restoring access while persistence remains can cause reinfection.", "options": ["Malicious persistence and the exploited cause", "Only the desktop wallpaper", "The number of helpdesk chairs"], "answer": 0, "tier": 3}, {"id": "cert4-4.8-scenario-4-8-2", "prompt": "A workstation is actively encrypting a shared folder. The response plan authorizes endpoint isolation. Relevant logs and volatile evidence may be useful.\n\nWhat should follow safe restoration?", "explanation": "Recovery validation and improvement complete the response loop.", "options": ["Stop monitoring forever", "Monitor for recurrence and record lessons learned", "Discard the incident timeline"], "answer": 1, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-4.9", "title": "Investigate across data sources", "core": 4, "objective": "4.9", "domain": 4, "type": "security", "requires": ["cert4-4.8"], "lore": "A good investigation separates observations from interpretations. Correlate network, endpoint, identity, application, and cloud evidence. Packet captures show content only when it is captured and readable; flow records show communication metadata rather than full payloads. Missing logs are not proof that an event never happened. Preserve original evidence, record time zones, and use controlled working copies. Do not let a convenient story outrun the available facts.\n\nFIELD NOTES\n\nPacket capture — A recording of network packets that can reveal protocol details and, where unencrypted, payload contents.\n\nNetwork flow record — Communication metadata such as endpoints, ports, timing, and volume without necessarily containing full packet payloads.\n\nDNS query log — A record of name-resolution requests useful for linking a client to requested domains.\n\nAuthentication log — A record of sign-in events, identities, results, and related context.\n\nEndpoint telemetry — Observations from a host such as process creation, file changes, and network connections.\n\nApplication log — Events generated by application functions that can show transactions, errors, or application-level access.\n\nCloud audit log — A record of administrative or resource actions within a cloud environment.\n\nVulnerability report — A structured record of identified weaknesses, affected resources, severity, and remediation context.\n\nEvidence hashing — Computing a digest to detect whether a collected evidence copy has changed since it was recorded.\n\nTimeline correlation — Combining time-aligned observations from different sources to reconstruct an event sequence.\n\nPUT IT IN CONTEXT\n\nAdditional evidence can come from firewall, IDS/IPS, proxy, web-server, database, and operating-system logs; dashboards and reports summarize those underlying records. Capture source, collection method, time zone, and integrity metadata. Do not claim absence from a dataset proves no activity occurred if collection was incomplete.", "example": "A proxy log shows a workstation contacted a suspicious host, a DNS log shows the earlier lookup, and endpoint telemetry identifies the originating process. A flow record can support volume and timing but cannot by itself show which document was transferred. State both your conclusion and its evidentiary limits.", "questions": [{"id": "cert4-4.9-practice-4-9-0", "prompt": "Which concept best fits this description? A recording of network packets that can reveal protocol details and, where unencrypted, payload contents.", "explanation": "Packet capture: A recording of network packets that can reveal protocol details and, where unencrypted, payload contents. The other choices describe different mechanisms or properties.", "options": ["Packet capture", "Network flow record", "Authentication log", "Cloud audit log"], "answer": 0, "tier": 1}, {"id": "cert4-4.9-practice-4-9-1", "prompt": "Which concept best fits this description? Communication metadata such as endpoints, ports, timing, and volume without necessarily containing full packet payloads.", "explanation": "Network flow record: Communication metadata such as endpoints, ports, timing, and volume without necessarily containing full packet payloads. The other choices describe different mechanisms or properties.", "options": ["DNS query log", "Endpoint telemetry", "Vulnerability report", "Network flow record"], "answer": 3, "tier": 1}, {"id": "cert4-4.9-match-4-9", "prompt": "Match the field notes to their meaning.", "explanation": "DNS query log: A record of name-resolution requests useful for linking a client to requested domains.\nEndpoint telemetry: Observations from a host such as process creation, file changes, and network connections.\nCloud audit log: A record of administrative or resource actions within a cloud environment.\nEvidence hashing: Computing a digest to detect whether a collected evidence copy has changed since it was recorded.", "left": ["DNS query log", "Endpoint telemetry", "Cloud audit log", "Evidence hashing"], "options": ["A record of administrative or resource actions within a cloud environment.", "A record of name-resolution requests useful for linking a client to requested domains.", "Computing a digest to detect whether a collected evidence copy has changed since it was recorded.", "Observations from a host such as process creation, file changes, and network connections."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-4.9-scenario-4-9-0", "prompt": "09:00 DNS: workstation7 asks for sync.bad.example\n09:01 proxy: workstation7 POST to sync.bad.example\n09:01 EDR: new unsigned process launched that connection\nFlow record: 40 MB outbound; TLS payload not available.\n\nWhich source links the connection to a process?", "explanation": "Endpoint telemetry supplies the observed process-to-connection relationship.", "options": ["The endpoint telemetry", "The hostname's spelling alone", "The office floor plan"], "answer": 0, "tier": 3}, {"id": "cert4-4.9-scenario-4-9-1", "prompt": "09:00 DNS: workstation7 asks for sync.bad.example\n09:01 proxy: workstation7 POST to sync.bad.example\n09:01 EDR: new unsigned process launched that connection\nFlow record: 40 MB outbound; TLS payload not available.\n\nCan the flow record alone prove exactly which file was sent?", "explanation": "Volume and timing do not identify exact content without additional evidence.", "options": ["Yes, byte counts reveal filenames", "No; it shows metadata, not the missing decrypted payload", "Yes, every TLS flow is readable"], "answer": 1, "tier": 3}, {"id": "cert4-4.9-scenario-4-9-2", "prompt": "09:00 DNS: workstation7 asks for sync.bad.example\n09:01 proxy: workstation7 POST to sync.bad.example\n09:01 EDR: new unsigned process launched that connection\nFlow record: 40 MB outbound; TLS payload not available.\n\nHow should you preserve collected evidence?", "explanation": "Integrity and documented handling support a defensible investigation.", "options": ["Edit the original logs until they match the theory", "Publish them publicly before analysis", "Keep controlled originals, hashes, and handling records"], "answer": 2, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.1", "title": "Connect decisions to governance", "core": 4, "objective": "5.1", "domain": 5, "type": "security", "requires": [], "lore": "Governance establishes direction, accountability, and oversight. Policies state expectations, standards define required specifics, procedures explain how, and guidelines advise. Match a document to its purpose rather than its length. Governance also identifies owners and exceptions, aligns obligations with business strategy, and defines who may accept risk. Security leadership should review whether requirements remain appropriate as laws, technology, and operations change.\n\nFIELD NOTES\n\nSecurity policy — A high-level management statement of required security expectations and responsibilities.\n\nSecurity standard — A mandatory, specific requirement used to implement a policy consistently.\n\nSecurity procedure — Step-by-step instructions for performing a defined task.\n\nSecurity guideline — Recommended practice that permits judgment rather than imposing a mandatory implementation.\n\nGovernance oversight — Accountable review of direction, risk decisions, and whether security outcomes meet organizational needs.\n\nData steward — A role performing day-to-day data management activities according to ownership and governance decisions.\n\nCustodian — A role implementing and maintaining technical or operational protections for information or systems.\n\nAcceptable use policy — Rules defining permitted and prohibited use of organizational technology and resources.\n\nPolicy exception — An approved, documented deviation with a rationale, owner, compensating safeguards, and review conditions.\n\nExternal obligation — A requirement arising outside internal policy, such as a contract or applicable regulatory duty.\n\nPUT IT IN CONTEXT\n\nGovernance may involve boards, committees, security officers, owners, custodians, and stewards. Set review and revision cycles. Policies commonly cover acceptable use, information security, business continuity, disaster recovery, incident response, development, and change. Local laws, industry obligations, and organizational structure influence implementation; assigning a title without authority does not establish accountability.", "example": "A policy says sensitive data must be protected in transit. A standard specifies approved transport settings. A procedure explains how administrators configure them. A guideline offers recommended design patterns. An exception needs accountable approval and an expiry, not a permanent undocumented bypass.", "questions": [{"id": "cert4-5.1-practice-5-1-0", "prompt": "Which concept best fits this description? A high-level management statement of required security expectations and responsibilities.", "explanation": "Security policy: A high-level management statement of required security expectations and responsibilities. The other choices describe different mechanisms or properties.", "options": ["Security standard", "Security guideline", "Custodian", "Security policy"], "answer": 3, "tier": 1}, {"id": "cert4-5.1-practice-5-1-1", "prompt": "Which concept best fits this description? A mandatory, specific requirement used to implement a policy consistently.", "explanation": "Security standard: A mandatory, specific requirement used to implement a policy consistently. The other choices describe different mechanisms or properties.", "options": ["Governance oversight", "Acceptable use policy", "Security standard", "Security procedure"], "answer": 2, "tier": 1}, {"id": "cert4-5.1-match-5-1", "prompt": "Match the field notes to their meaning.", "explanation": "Security procedure: Step-by-step instructions for performing a defined task.\nGovernance oversight: Accountable review of direction, risk decisions, and whether security outcomes meet organizational needs.\nCustodian: A role implementing and maintaining technical or operational protections for information or systems.\nPolicy exception: An approved, documented deviation with a rationale, owner, compensating safeguards, and review conditions.", "left": ["Security procedure", "Governance oversight", "Custodian", "Policy exception"], "options": ["A role implementing and maintaining technical or operational protections for information or systems.", "Step-by-step instructions for performing a defined task.", "An approved, documented deviation with a rationale, owner, compensating safeguards, and review conditions.", "Accountable review of direction, risk decisions, and whether security outcomes meet organizational needs."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.2", "title": "Turn uncertainty into a risk decision", "core": 4, "objective": "5.2", "domain": 5, "type": "security", "requires": ["cert4-5.1"], "lore": "Risk combines uncertainty about a harmful event with its impact on objectives. Define the asset, threat, weakness, likelihood, and consequence before scoring. Qualitative labels can help prioritize; quantitative estimates make assumptions explicit but are not precise predictions. Compare the cost of treatment with expected loss and obligations. Risk acceptance belongs to an accountable business authority, not whichever technician closes the ticket.\n\nFIELD NOTES\n\nRisk register — A maintained record of identified risks, owners, assessments, treatments, and review status.\n\nRisk appetite — The broad amount and type of risk an organization is willing to pursue or retain.\n\nRisk tolerance — Specific acceptable variation or limits for a risk-related outcome.\n\nInherent risk — Risk assessed before considering the relevant controls or treatments.\n\nResidual risk — Risk remaining after controls or treatments have been applied.\n\nRisk avoidance — Eliminating a risky activity or exposure rather than continuing it with safeguards.\n\nRisk transfer — Shifting defined financial or contractual consequences to another party, such as through insurance, without eliminating all responsibility.\n\nRisk acceptance — An accountable decision to retain a known risk under defined conditions.\n\nSingle loss expectancy — A modeled loss from one event, commonly calculated as asset value multiplied by exposure factor.\n\nAnnualized loss expectancy — A modeled annual loss calculated as single loss expectancy multiplied by annualized rate of occurrence.\n\nPUT IT IN CONTEXT\n\nRisk assessment may be one-time, recurring, event-driven, qualitative, or quantitative. A risk matrix combines likelihood and impact. A business impact analysis identifies critical functions and dependencies. MTTR estimates repair time; MTBF concerns average time between failures. A key risk indicator is a measurement of changing exposure. Mitigation reduces risk; avoidance ends the activity; transfer allocates consequences; acceptance retains risk under authority.", "example": "An asset is worth $100,000. A modeled event would lose 20% of that value and occurs once every five years on average. SLE is $20,000 and ARO is 0.2, giving ALE of $4,000. The model informs a decision but does not mean losses will arrive smoothly at $4,000 each year.", "questions": [{"id": "cert4-5.2-practice-5-2-0", "prompt": "Which concept best fits this description? A maintained record of identified risks, owners, assessments, treatments, and review status.", "explanation": "Risk register: A maintained record of identified risks, owners, assessments, treatments, and review status. The other choices describe different mechanisms or properties.", "options": ["Risk appetite", "Inherent risk", "Risk transfer", "Risk register"], "answer": 3, "tier": 1}, {"id": "cert4-5.2-practice-5-2-1", "prompt": "Which concept best fits this description? The broad amount and type of risk an organization is willing to pursue or retain.", "explanation": "Risk appetite: The broad amount and type of risk an organization is willing to pursue or retain. The other choices describe different mechanisms or properties.", "options": ["Residual risk", "Risk acceptance", "Risk appetite", "Risk tolerance"], "answer": 2, "tier": 1}, {"id": "cert4-5.2-match-5-2", "prompt": "Match the field notes to their meaning.", "explanation": "Risk tolerance: Specific acceptable variation or limits for a risk-related outcome.\nResidual risk: Risk remaining after controls or treatments have been applied.\nRisk transfer: Shifting defined financial or contractual consequences to another party, such as through insurance, without eliminating all responsibility.\nSingle loss expectancy: A modeled loss from one event, commonly calculated as asset value multiplied by exposure factor.", "left": ["Risk tolerance", "Residual risk", "Risk transfer", "Single loss expectancy"], "options": ["Shifting defined financial or contractual consequences to another party, such as through insurance, without eliminating all responsibility.", "Specific acceptable variation or limits for a risk-related outcome.", "A modeled loss from one event, commonly calculated as asset value multiplied by exposure factor.", "Risk remaining after controls or treatments have been applied."], "answer": [1, 3, 0, 2], "tier": 2}, {"id": "cert4-5.2-scenario-5-2-0", "prompt": "A modeled asset value is $100,000. One event loses 20% of value. The estimated event frequency is once per five years.\n\nWhat is the modeled single loss expectancy?", "explanation": "$100,000 × 0.20 = $20,000 for one modeled event.", "options": ["$500,000", "$20,000", "$4,000"], "answer": 1, "tier": 3}, {"id": "cert4-5.2-scenario-5-2-1", "prompt": "A modeled asset value is $100,000. One event loses 20% of value. The estimated event frequency is once per five years.\n\nWhat is the modeled annualized loss expectancy?", "explanation": "Annual frequency is 0.2, so $20,000 × 0.2 = $4,000.", "options": ["$100,000", "$20,000", "$4,000"], "answer": 2, "tier": 3}, {"id": "cert4-5.2-scenario-5-2-2", "prompt": "A modeled asset value is $100,000. One event loses 20% of value. The estimated event frequency is once per five years.\n\nWho should accept residual business risk?", "explanation": "Risk acceptance requires defined authority and accountability.", "options": ["An accountable authorized business risk owner", "Whoever happens to see the alert first", "An anonymous external caller"], "answer": 0, "tier": 3}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.3", "title": "Manage trust in suppliers", "core": 4, "objective": "5.3", "domain": 5, "type": "security", "requires": ["cert4-5.2"], "lore": "Third-party risk starts before procurement and continues through termination. Understand what a vendor can access, which service depends on it, and how evidence supports its claims. Contracts should define responsibilities, notification, data handling, availability, and exit arrangements. A questionnaire is not an independent test, and a reputable supplier can still have a poorly configured integration. Review subcontractors and concentration risk where they affect your service.\n\nFIELD NOTES\n\nVendor due diligence — Investigating a supplier's security, reliability, and suitability before committing to a relationship.\n\nVendor monitoring — Ongoing review of supplier performance, changes, risks, and contractual obligations.\n\nService-level agreement — A contract component specifying measurable service expectations and related responsibilities.\n\nNon-disclosure agreement — An agreement restricting disclosure or use of confidential information.\n\nStatement of work — A description of specific tasks, deliverables, boundaries, and responsibilities for an engagement.\n\nMaster service agreement — An overarching agreement defining general terms for a service relationship.\n\nRight-to-audit clause — A contractual provision establishing agreed rights to assess or inspect relevant controls or evidence.\n\nRules of engagement — Authorized scope, constraints, communications, and boundaries for a security testing activity.\n\nSupply-chain assessment — Evaluating risks introduced by upstream providers, components, dependencies, and subcontractors.\n\nVendor offboarding — Ending a relationship by removing access and resolving data return, deletion, transfer, and continuity requirements.\n\nPUT IT IN CONTEXT\n\nUse independent reports, questionnaires, tests, onsite review, and evidence according to supplier criticality. Agreements can include MOU, MOA, SLA, NDA, business-partner terms, and detailed statements of work. Assess conflicts of interest and subcontractors. Selection, onboarding, monitoring, incident coordination, and termination are all parts of the relationship.", "example": "A payroll vendor will store employee data and use a subprocessor. Assess controls and locations, define breach notification and return/deletion requirements, restrict the integration account, and monitor the relationship. A signed NDA alone does not establish availability or secure handling.", "questions": [{"id": "cert4-5.3-practice-5-3-0", "prompt": "Which concept best fits this description? Investigating a supplier's security, reliability, and suitability before committing to a relationship.", "explanation": "Vendor due diligence: Investigating a supplier's security, reliability, and suitability before committing to a relationship. The other choices describe different mechanisms or properties.", "options": ["Vendor monitoring", "Non-disclosure agreement", "Right-to-audit clause", "Vendor due diligence"], "answer": 3, "tier": 1}, {"id": "cert4-5.3-practice-5-3-1", "prompt": "Which concept best fits this description? Ongoing review of supplier performance, changes, risks, and contractual obligations.", "explanation": "Vendor monitoring: Ongoing review of supplier performance, changes, risks, and contractual obligations. The other choices describe different mechanisms or properties.", "options": ["Statement of work", "Rules of engagement", "Vendor monitoring", "Service-level agreement"], "answer": 2, "tier": 1}, {"id": "cert4-5.3-match-5-3", "prompt": "Match the field notes to their meaning.", "explanation": "Service-level agreement: A contract component specifying measurable service expectations and related responsibilities.\nStatement of work: A description of specific tasks, deliverables, boundaries, and responsibilities for an engagement.\nRight-to-audit clause: A contractual provision establishing agreed rights to assess or inspect relevant controls or evidence.\nSupply-chain assessment: Evaluating risks introduced by upstream providers, components, dependencies, and subcontractors.", "left": ["Service-level agreement", "Statement of work", "Right-to-audit clause", "Supply-chain assessment"], "options": ["A contractual provision establishing agreed rights to assess or inspect relevant controls or evidence.", "A contract component specifying measurable service expectations and related responsibilities.", "Evaluating risks introduced by upstream providers, components, dependencies, and subcontractors.", "A description of specific tasks, deliverables, boundaries, and responsibilities for an engagement."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.4", "title": "Handle obligations and privacy deliberately", "core": 4, "objective": "5.4", "domain": 5, "type": "security", "requires": ["cert4-5.3"], "lore": "Compliance demonstrates conformance to applicable requirements; it does not establish that every security risk is solved. Determine which obligations apply and who is accountable, then gather evidence and monitor changes. Privacy concerns appropriate processing of information about people, including purpose, access, retention, and rights. Legal duties vary by jurisdiction, so involve qualified organizational advice rather than assuming one rule applies everywhere.\n\nFIELD NOTES\n\nCompliance monitoring — Checking whether required controls and behaviors continue to meet applicable obligations.\n\nAttestation — A formal assertion about a condition or control state made by an accountable party.\n\nData subject — The individual to whom personal information relates.\n\nData controller — The role determining the purposes and means of processing personal information in a controller/processor framework.\n\nData processor — A party processing personal information on behalf of a controller under applicable arrangements.\n\nPrivacy impact assessment — A structured evaluation of how an activity may affect personal information and privacy risks.\n\nData inventory — A record of what information is held, where it resides, how it is used, and who is responsible.\n\nRetention obligation — A requirement to keep specified information for an applicable period or purpose.\n\nRight-to-erasure request — A request to delete personal information whose handling depends on applicable law and permitted exceptions.\n\nNoncompliance consequence — An adverse outcome such as sanctions, financial loss, contractual impact, or reputational damage from failing an obligation.\n\nPUT IT IN CONTEXT\n\nCompliance can involve internal and external reporting, due diligence, audits, and continuous monitoring. Noncompliance can cause fines, contractual loss, sanctions, or reputational harm. Privacy roles, jurisdiction, consent, purpose, ownership, inventory, and retention matter. Legal hold and other valid obligations can limit deletion; route requests through the applicable process rather than promising universal erasure.", "example": "A customer asks to delete an account. Verify the request, identify relevant records and processors, assess retention or legal-hold obligations, and execute the authorized response. Deleting one profile screen while backups and vendor copies are unmanaged does not establish that the request was fulfilled.", "questions": [{"id": "cert4-5.4-practice-5-4-0", "prompt": "Which concept best fits this description? Checking whether required controls and behaviors continue to meet applicable obligations.", "explanation": "Compliance monitoring: Checking whether required controls and behaviors continue to meet applicable obligations. The other choices describe different mechanisms or properties.", "options": ["Attestation", "Data controller", "Data inventory", "Compliance monitoring"], "answer": 3, "tier": 1}, {"id": "cert4-5.4-practice-5-4-1", "prompt": "Which concept best fits this description? A formal assertion about a condition or control state made by an accountable party.", "explanation": "Attestation: A formal assertion about a condition or control state made by an accountable party. The other choices describe different mechanisms or properties.", "options": ["Data processor", "Retention obligation", "Attestation", "Data subject"], "answer": 2, "tier": 1}, {"id": "cert4-5.4-match-5-4", "prompt": "Match the field notes to their meaning.", "explanation": "Data subject: The individual to whom personal information relates.\nData processor: A party processing personal information on behalf of a controller under applicable arrangements.\nData inventory: A record of what information is held, where it resides, how it is used, and who is responsible.\nRight-to-erasure request: A request to delete personal information whose handling depends on applicable law and permitted exceptions.", "left": ["Data subject", "Data processor", "Data inventory", "Right-to-erasure request"], "options": ["A record of what information is held, where it resides, how it is used, and who is responsible.", "The individual to whom personal information relates.", "A request to delete personal information whose handling depends on applicable law and permitted exceptions.", "A party processing personal information on behalf of a controller under applicable arrangements."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.5", "title": "Use assessments to answer the right question", "core": 4, "objective": "5.5", "domain": 5, "type": "security", "requires": ["cert4-5.4"], "lore": "An audit compares evidence against defined criteria. A vulnerability assessment identifies weaknesses. A penetration test attempts authorized exploitation to demonstrate impact within agreed boundaries. None guarantees the absence of all problems. Define scope, permissions, reporting, and evidence handling before tests begin. Independence matters when assurance is the purpose; self-assessment remains useful but should be labeled honestly.\n\nFIELD NOTES\n\nInternal audit — An assessment performed within an organization against defined criteria with an appropriate assurance function.\n\nExternal audit — An assessment performed by an outside party to evaluate conformance against agreed criteria.\n\nSelf-assessment — An organization or team evaluating its own controls, with the independence limitations made explicit.\n\nPenetration test — An authorized attempt to exploit weaknesses within defined scope to evaluate security impact.\n\nKnown-environment test — A test in which substantial target information is provided to the testers.\n\nUnknown-environment test — A test in which testers begin with little supplied knowledge of the target environment.\n\nPartially known-environment test — A test in which some target information is provided while other details must be discovered.\n\nPassive reconnaissance — Gathering target information without directly interacting with the target systems being assessed.\n\nActive reconnaissance — Directly interacting with a target to discover information, subject to authorization and agreed limits.\n\nAssessment report — A documented account of scope, methods, evidence, findings, limitations, and recommended actions.\n\nPUT IT IN CONTEXT\n\nAssessment evidence may include configurations, records, interviews, observations, and test results. Testing can be physical, offensive, defensive, or collaborative under defined authorization. Reconcile findings to scope and criteria, distinguish an audit opinion from a tool result, and report limitations honestly. An untested component is not automatically secure.", "example": "Management asks whether remote-access controls satisfy a contractual requirement. An audit can inspect criteria and evidence. If management instead asks whether an attacker could chain weaknesses into access, an authorized penetration test addresses that question. The two can inform each other without being interchangeable.", "questions": [{"id": "cert4-5.5-practice-5-5-0", "prompt": "Which concept best fits this description? An assessment performed within an organization against defined criteria with an appropriate assurance function.", "explanation": "Internal audit: An assessment performed within an organization against defined criteria with an appropriate assurance function. The other choices describe different mechanisms or properties.", "options": ["External audit", "Penetration test", "Partially known-environment test", "Internal audit"], "answer": 3, "tier": 1}, {"id": "cert4-5.5-practice-5-5-1", "prompt": "Which concept best fits this description? An assessment performed by an outside party to evaluate conformance against agreed criteria.", "explanation": "External audit: An assessment performed by an outside party to evaluate conformance against agreed criteria. The other choices describe different mechanisms or properties.", "options": ["Known-environment test", "Passive reconnaissance", "External audit", "Self-assessment"], "answer": 2, "tier": 1}, {"id": "cert4-5.5-match-5-5", "prompt": "Match the field notes to their meaning.", "explanation": "Self-assessment: An organization or team evaluating its own controls, with the independence limitations made explicit.\nKnown-environment test: A test in which substantial target information is provided to the testers.\nPartially known-environment test: A test in which some target information is provided while other details must be discovered.\nActive reconnaissance: Directly interacting with a target to discover information, subject to authorization and agreed limits.", "left": ["Self-assessment", "Known-environment test", "Partially known-environment test", "Active reconnaissance"], "options": ["A test in which some target information is provided while other details must be discovered.", "An organization or team evaluating its own controls, with the independence limitations made explicit.", "Directly interacting with a target to discover information, subject to authorization and agreed limits.", "A test in which substantial target information is provided to the testers."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}, {"id": "cert4-5.6", "title": "Build habits that survive pressure", "core": 4, "objective": "5.6", "domain": 5, "type": "security", "requires": ["cert4-5.5"], "lore": "Awareness should help people recognize and report risk without making them afraid to speak up. Tailor training to role and context, including remote work, removable media, passwords, and social engineering. Teach a clear reporting route and reinforce it repeatedly. Measure useful behavior such as reporting speed and correct handling, not just attendance. A phishing simulation should be authorized, ethical, and followed by constructive learning.\n\nFIELD NOTES\n\nPhishing recognition — Identifying suspicious requests through context, destination, urgency, and verification rather than relying only on spelling errors.\n\nSecurity reporting channel — A known way for users to report suspicious events to the appropriate response team.\n\nRole-based training — Teaching security practices relevant to a person's actual responsibilities and exposure.\n\nSituational awareness — Recognizing relevant surroundings and context, such as an unknown person following someone through a secure door.\n\nOperational security awareness — Avoiding disclosures that let others infer sensitive plans, access, or organizational patterns.\n\nRemovable media awareness — Handling unknown drives and cables cautiously instead of connecting them to trusted systems.\n\nPassword management training — Teaching unique secrets, approved password managers, and secure recovery practices.\n\nRemote-work awareness — Teaching safe handling of devices, communications, and information outside controlled office environments.\n\nRecurring awareness — Reinforcing and updating training over time instead of relying only on one onboarding event.\n\nTraining effectiveness measurement — Evaluating behavioral outcomes such as correct reporting and reduced risky actions, not merely course attendance.\n\nPUT IT IN CONTEXT\n\nRecognize risky, unexpected, and unintentional behavior without treating every mistake as malicious intent. Teach insider-risk reporting, social engineering defenses, safe passwords, media handling, remote work, and operational discretion. Develop, deliver, and assess the program repeatedly. Make the reporting path clear enough to use under pressure.", "example": "An employee reports that they approved an unexpected MFA prompt. Thank them, escalate through the response route, and secure the account as appropriate. Shaming the employee would make the next incident harder to discover. Update training to explain prompt fatigue and the correct way to reject and report it.", "questions": [{"id": "cert4-5.6-practice-5-6-0", "prompt": "Which concept best fits this description? Identifying suspicious requests through context, destination, urgency, and verification rather than relying only on spelling errors.", "explanation": "Phishing recognition: Identifying suspicious requests through context, destination, urgency, and verification rather than relying only on spelling errors. The other choices describe different mechanisms or properties.", "options": ["Security reporting channel", "Situational awareness", "Password management training", "Phishing recognition"], "answer": 3, "tier": 1}, {"id": "cert4-5.6-practice-5-6-1", "prompt": "Which concept best fits this description? A known way for users to report suspicious events to the appropriate response team.", "explanation": "Security reporting channel: A known way for users to report suspicious events to the appropriate response team. The other choices describe different mechanisms or properties.", "options": ["Operational security awareness", "Remote-work awareness", "Security reporting channel", "Role-based training"], "answer": 2, "tier": 1}, {"id": "cert4-5.6-match-5-6", "prompt": "Match the field notes to their meaning.", "explanation": "Role-based training: Teaching security practices relevant to a person's actual responsibilities and exposure.\nOperational security awareness: Avoiding disclosures that let others infer sensitive plans, access, or organizational patterns.\nPassword management training: Teaching unique secrets, approved password managers, and secure recovery practices.\nRecurring awareness: Reinforcing and updating training over time instead of relying only on one onboarding event.", "left": ["Role-based training", "Operational security awareness", "Password management training", "Recurring awareness"], "options": ["Teaching unique secrets, approved password managers, and secure recovery practices.", "Teaching security practices relevant to a person's actual responsibilities and exposure.", "Reinforcing and updating training over time instead of relying only on one onboarding event.", "Avoiding disclosures that let others infer sensitive plans, access, or organizational patterns."], "answer": [1, 3, 0, 2], "tier": 2}], "sources": [{"id": "objectives", "title": "CompTIA SY0-701 exam objectives · verified document 6.0", "url": "https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-(6-0).pdf?sfvrsn=204179cc_6", "accessed": "2026-11-03"}, {"id": "glossary", "title": "NIST CSRC security glossary · terminology reference", "url": "https://csrc.nist.gov/glossary", "accessed": "2026-11-03"}, {"id": "controls", "title": "NIST SP 800-53 Rev. 5 · control families and reference guidance", "url": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final", "accessed": "2026-11-03"}, {"id": "zero-trust", "title": "NIST SP 800-207 · zero trust reference", "url": "https://csrc.nist.gov/pubs/sp/800/207/final", "accessed": "2026-11-03"}, {"id": "incident", "title": "NIST SP 800-61 Rev. 3 · current response guidance", "url": "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "accessed": "2026-11-03"}, {"id": "injection", "title": "OWASP · SQL injection prevention reference", "url": "https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html", "accessed": "2026-11-03"}]}];
